#[test]
fn test_builtin_first_on_non_array_errors() -> Result<()> {
    // jq: 5 | first => error. The error goes to stderr and nothing to stdout,
    // and the process exits 5 so the failure is visible to a shell (#355).
    let (output, code) = spawn_jq(&["first"], Some(b"5"))?;

    let stdout = String::from_utf8(output.stdout)?;
    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(stdout.trim(), "");
    // jq defines `first` as `.[0]`, so it reports an indexing error (#356);
    // the exact wording is pinned against jq-1.7.1 in
    // tests/data/jq-error-messages.tsv.
    assert!(
        stderr.contains("Cannot index number with number"),
        "Should report jq's indexing error for `5 | first`: {stderr}"
    );
    assert_eq!(
        code, 5,
        "An uncaught eval error must exit 5 like jq: {stderr}"
    );
    Ok(())
}

/// Run a filter and return its stderr, for cases whose observable behaviour is
/// the error message rather than stdout.
///
/// The jq golden corpus cannot host these: it compares stdout only and requires
/// exit 0.
fn jq_stderr(filter: &str, input: &str, extra_args: &[&str]) -> Result<String> {
    let mut args: Vec<&str> = extra_args.to_vec();
    args.push(filter);
    let (output, _code) = spawn_jq(&args, Some(input.as_bytes()))?;
    Ok(String::from_utf8(output.stderr)?)
}

/// Indexing by a key whose *kind* cannot index the container reports jq's
/// wording verbatim (#360).
///
/// The messages are transcribed from jq 1.7.1. Note the string form inserts the
/// key raw rather than JSON-escaped — `--arg k 'a"b'` really does produce
/// `Cannot index array with string "a"b"` in jq.
#[test]
fn test_cannot_index_error_wording() -> Result<()> {
    let cases: &[(&str, &str, &[&str], &str)] = &[
        (".[null]", "{}", &[], "Cannot index object with null"),
        (".[null]", "[]", &[], "Cannot index array with null"),
        (".[null]", "null", &[], "Cannot index null with null"),
        (".[true]", "{}", &[], "Cannot index object with boolean"),
        (".[{}]", "{}", &[], "Cannot index object with object"),
        (".[[1]]", "{}", &[], "Cannot index object with array"),
        (
            ".[$k]",
            "[1,2]",
            &["--arg", "k", "a"],
            r#"Cannot index array with string "a""#,
        ),
        (
            ".[$k]",
            r#""s""#,
            &["--arg", "k", "a"],
            r#"Cannot index string with string "a""#,
        ),
        // The same wording must come out of the path/assignment pre-pass, not
        // just the value path.
        (".[null] = 1", "{}", &[], "Cannot index object with null"),
        ("path(.[null])", "{}", &[], "Cannot index object with null"),
        ("del(.[null])", "{}", &[], "Cannot index object with null"),
    ];

    for (filter, input, args, expected) in cases {
        let stderr = jq_stderr(filter, input, args)?;
        assert!(
            stderr.contains(expected),
            "`{filter}` on `{input}` should report {expected:?}, got: {stderr}"
        );
    }
    Ok(())
}

/// A *literal* key reports the same thing a computed one does.
///
/// The pair in each row is the same query written two ways. They travel
/// different routes to get there — a constant key folds to
/// `Expr::Field`/`Expr::Index` at parse time (#360), a computed one stays an
/// `Expr::IndexExpr` and dispatches on the key's kind at run time — and each
/// route raises its error from its own site, so nothing but a test holds them to
/// one wording. A message that changes with the spelling of the key is worse
/// than either message alone.
///
/// Nothing else covers the pairing: the #356 error corpus probes each spelling
/// against jq independently, which catches a drift from jq but not a drift
/// between the two spellings if both were to move together.
#[test]
fn test_cannot_index_wording_is_spelling_independent() -> Result<()> {
    // (literal filter, computed filter, extra args, input, expected message)
    let cases: &[(&str, &str, &[&str], &str, &str)] = &[
        (
            ".[0]",
            ".[$n]",
            &["--argjson", "n", "0"],
            r#"{"a":1}"#,
            "Cannot index object with number",
        ),
        (
            r#".["x"]"#,
            ".[$k]",
            &["--arg", "k", "x"],
            "[1,2]",
            r#"Cannot index array with string "x""#,
        ),
        (
            ".x",
            ".[$k]",
            &["--arg", "k", "x"],
            "[1,2]",
            r#"Cannot index array with string "x""#,
        ),
        (
            ".a",
            ".[$k]",
            &["--arg", "k", "a"],
            "123",
            r#"Cannot index number with string "a""#,
        ),
        (
            ".[0]",
            ".[$n]",
            &["--argjson", "n", "0"],
            r#""s""#,
            "Cannot index string with number",
        ),
    ];

    for (literal, computed, args, input, expected) in cases {
        for filter in [literal, computed] {
            let stderr = jq_stderr(filter, input, args)?;
            assert!(
                stderr.contains(expected),
                "`{filter}` on `{input}` should report {expected:?}, got: {stderr}"
            );
        }
    }
    Ok(())
}

/// A NaN key reads as null but must never *write*.
///
/// `f64 as i64` maps NaN to `0`, so the natural implementation silently reads —
/// and, in an assignment, overwrites — element zero. jq yields null on the read
/// and errors on the write; both halves are checked here because only the read
/// half is observable in the golden corpus (`index_nan_key`).
#[test]
fn test_nan_key_reads_null_and_rejects_writes() -> Result<()> {
    let (output, _) = run_jq_stdin("[.[nan]]", "[10,20,30]", &["-c"])?;
    assert_eq!(output.trim(), "[null]");

    for filter in [".[nan] = 5", ".[nan] |= 5", "path(.[nan])", "del(.[nan])"] {
        let stderr = jq_stderr(filter, "[10,20,30]", &[])?;
        assert!(
            stderr.contains("Cannot set array element at NaN index"),
            "`{filter}` should refuse a NaN index, got: {stderr}"
        );
        let (output, _) = run_jq_stdin(filter, "[10,20,30]", &["-c"])?;
        assert_eq!(
            output.trim(),
            "",
            "`{filter}` must not emit a mutated document"
        );
    }
    Ok(())
}

/// `?` suppresses a bad-key error rather than propagating it.
///
/// Regression guard for the `eval_generic` fallback: routing an unhandled
/// expression through `full_eval` restarts with `optional = false`, which
/// silently dropped the `?` here.
#[test]
fn test_optional_suppresses_cannot_index() -> Result<()> {
    let (output, _) = run_jq_stdin(".[null]?", "{}", &["-c"])?;
    assert_eq!(output.trim(), "");
    let stderr = jq_stderr(".[null]?", "{}", &[])?;
    assert!(
        !stderr.contains("Cannot index"),
        "`?` should suppress the error, got: {stderr}"
    );
    Ok(())
}

/// `?` covers the indexing, not the key expression.
///
/// jq's `.[K]?` is `try (E[K])` only over the index step: `.[error("boom")]?`
/// still raises `boom`, and walking `..` onto a string with `.[.k]?` still fails
/// on the key lookup. Passing the enclosing `optional` down into the key's
/// evaluation made succinctly strictly more forgiving than jq — `[.. | .[.k]?]`
/// returned `[1]` where jq errors.
#[test]
fn test_optional_does_not_suppress_key_errors() -> Result<()> {
    let cases: &[(&str, &str, &str)] = &[
        (
            "[.. | .[.k]?]",
            r#"{"k":"a","a":1}"#,
            r#"Cannot index string with string "k""#,
        ),
        (".[error(\"boom\")]?", r#"{"a":1}"#, "boom"),
    ];

    for (filter, input, expected) in cases {
        let stderr = jq_stderr(filter, input, &[])?;
        assert!(
            stderr.contains(expected),
            "`{filter}` should propagate the key error {expected:?}, got: {stderr}"
        );
    }

    // `try` still catches what `?` declines to swallow, so the error is
    // recoverable — it is raised, not fatal by construction.
    let (output, _) = run_jq_stdin(
        r#"[.. | try .[.k] catch "E"]"#,
        r#"{"k":"a","a":1}"#,
        &["-c"],
    )?;
    assert_eq!(output.trim(), r#"[1,"E","E"]"#);
    Ok(())
}

#[test]
fn test_contains_type_mismatch_errors() -> Result<()> {
    // jq: `1 | contains("a")` is an error, not `false` (#358). This exercises the
    // CLI's generic evaluator, which reaches the check by delegating to the full
    // one. Like `first` above, the exit status is not asserted: runtime eval
    // errors still exit 0 rather than jq's 5 (#355).
    let (output, _code) = spawn_jq(&["-c", r#"contains("a")"#], Some(b"1"))?;

    let stdout = String::from_utf8(output.stdout)?;
    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(stdout.trim(), "", "no `false` on stdout: {stdout}");
    assert!(
        stderr.contains(r#"number (1) and string ("a") cannot have their containment checked"#),
        "Should report jq's containment error: {stderr}"
    );
    Ok(())
}

#[test]
fn test_builtin_keys() -> Result<()> {
    let (output, code) = run_jq_stdin("keys", r#"{"z":1,"a":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), r#"["a","z"]"#);
    Ok(())
}

#[test]
fn test_builtin_map() -> Result<()> {
    let (output, code) = run_jq_stdin("map(. * 2)", r"[1,2,3]", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), "[2,4,6]");
    Ok(())
}

#[test]
fn test_builtin_select() -> Result<()> {
    let (output, code) = run_jq_stdin(".[] | select(. > 2)", r"[1,2,3,4,5]", &[])?;
    assert_eq!(code, 0);
    assert_eq!(output, "3\n4\n5\n");
    Ok(())
}

/// #1645: `push_generic_truthiness`'s `OneCursor`/`ManyCursor` arms swapped a
/// full materializing `to_owned_cursor(&c).is_truthy()` for the O(1)
/// `DocumentCursor::is_falsy()` -- caught by review that `is_falsy()` itself
/// is deliberately silent on a decode failure or a #1194 structural error
/// (its own doc comment: "conservative assumption", matching
/// `--exit-status`'s existing best-effort use of it), where the removed
/// materializing path used to raise. `select` must still raise here rather
/// than silently treating the value as truthy and passing it through.
#[test]
fn test_select_raises_on_decode_failure_instead_of_silently_truthy_1645() -> Result<()> {
    // `\x` is not a valid JSON escape -- structurally a string token, but
    // its bytes don't decode (#1247's own trigger shape).
    let (stdout, stderr, code) = run_jq_full(&[".[] | select(.)"], Some(r#"["\x"]"#))
        .unwrap_or_else(|e| panic!("`select(.)` failed to run: {e}"));
    assert_eq!(
        code, 5,
        "an undecodable value must not be silently treated as truthy\nstdout: {stdout:?}\nstderr: {stderr:?}"
    );
    assert!(
        stderr.contains("invalid escape sequence"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// #1645 sibling case: a *structurally* malformed value (#1194 -- a token
/// the semi-index accepted as a span but couldn't classify) must also still
/// raise through `select`'s truthiness check, not silently pass through.
#[test]
fn test_select_raises_on_structural_error_instead_of_silently_truthy_1645() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&[".[] | select(.)"], Some("[xyz123]"))
        .unwrap_or_else(|e| panic!("`select(.)` failed to run: {e}"));
    assert_eq!(
        code, 5,
        "a structurally malformed value must not be silently treated as truthy\nstdout: {stdout:?}\nstderr: {stderr:?}"
    );
    assert!(
        stderr.contains("unexpected character"),
        "expected the #1194 structural-error message on stderr: {stderr:?}"
    );
    Ok(())
}

/// #1645: the same decode failure, but nested a level below the value
/// `select`'s condition actually resolves to -- `.bad` resolves to the
/// *array*, not the bad string directly, so this only passes if the
/// truthiness check recurses into container contents rather than checking
/// only the condition's own top-level cursor (an earlier version of this
/// fix did exactly that and silently missed this shape -- caught by
/// review).
#[test]
fn test_select_raises_on_decode_failure_nested_in_container_1645() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(
        &["select(.bad) | .keep"],
        Some(r#"{"bad": ["\x"], "keep": 5}"#),
    )
    .unwrap_or_else(|e| panic!("`select(.bad)` failed to run: {e}"));
    assert_eq!(
        code, 5,
        "a decode failure nested inside the condition's container must still raise\nstdout: {stdout:?}\nstderr: {stderr:?}"
    );
    assert!(
        stderr.contains("invalid escape sequence"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// #1645 sibling case: a #1194 structural error nested a level below the
/// condition's own top-level cursor.
#[test]
fn test_select_raises_on_structural_error_nested_in_container_1645() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(
        &["select(.bad) | .keep"],
        Some(r#"{"bad": [xyz123], "keep": 5}"#),
    )
    .unwrap_or_else(|e| panic!("`select(.bad)` failed to run: {e}"));
    assert_eq!(
        code, 5,
        "a structural error nested inside the condition's container must still raise\nstdout: {stdout:?}\nstderr: {stderr:?}"
    );
    assert!(
        stderr.contains("unexpected character"),
        "expected the #1194 structural-error message on stderr: {stderr:?}"
    );
    Ok(())
}

/// Runs `succinctly jq <extra_args> <filter>` over `doc` and asserts it
/// raises with `code` and a stderr containing `expect_stderr` -- shared by
/// [`test_select_and_materialize_agree_on_corruption_1645`]'s three
/// comparison arms so each one asserts on the *message*, not just the exit
/// code (#1803 code review: an exit-code-only check can't tell "the expected
/// corruption was caught" from "an unrelated bug in this arm's own code path
/// happened to raise the same code").
fn assert_jq_raises(
    label: &str,
    op_label: &str,
    extra_args: &[&str],
    filter: &str,
    doc: &str,
    code: i32,
    expect_stderr: &str,
) {
    let mut args: Vec<&str> = extra_args.to_vec();
    args.push(filter);
    let (out, err, actual_code) = run_jq_full(&args, Some(doc))
        .unwrap_or_else(|e| panic!("[{label}] {op_label} run failed: {e}"));
    assert_eq!(
        actual_code, code,
        "[{label}] {op_label} must raise\nstdout: {out:?}\nstderr: {err:?}"
    );
    assert!(
        err.contains(expect_stderr),
        "[{label}] {op_label} stderr must contain {expect_stderr:?}\nstderr: {err:?}"
    );
}

/// #1645 code review: `push_generic_truthiness_cursor_error` is a second,
/// hand-copied implementation of the same "walk and raise on corruption"
/// predicate `to_owned_at_depth`/`to_owned_cursor_at_depth`/
/// `cursor_to_owned_at_depth` (`lazy.rs`) already implement for
/// materialization -- the exact "duplicated predicate" shape this repo's own
/// testing guidance warns diverges silently unless a test pins that every
/// site agrees, not just that each is individually correct (see the
/// `testing` skill and CLAUDE.md's "Duplicated predicates diverge silently"
/// note, #106). #1803 extended this from 2 sites to 3: `select(.bad) | .keep`
/// (`push_generic_truthiness_cursor_error`), `-Sc .bad` (`to_owned_at_depth`,
/// confirmed live via temporary tracing -- `-S` does *not* route through the
/// cursor-aware sibling despite the name resemblance), and `-e .bad`
/// (`cursor_to_owned_at_depth`, `lazy.rs` -- a JSON-only fourth
/// implementation with no `DocumentValue`/`DocumentCursor` generic bound,
/// reached only via `--exit-status`'s `JqValue::materialize()` path, #1098's
/// own doc comment). All three agree on every case below; #1803 also probed
/// for a genuine cross-site divergence and found none here -- the real bug
/// that investigation surfaced (#1960) turned out to be an unrelated YAML
/// flow-scalar parser bug, not a traversal-function disagreement.
///
/// **Known scope limit** (#1803 code review): this is example-based
/// coverage over a hand-picked case list, not an exhaustive or randomized
/// check -- see `.claude/skills/testing/SKILL.md`'s "Invariant Tests Over
/// Duplicated Logic" section for why a corpus-wide or fuzzed cross-check
/// catches more of this bug class than a fixed list ever can. A differential
/// fuzzer varying nesting depth/format/malformation kind across these same
/// three CLI paths would close that gap; not attempted here to keep this PR
/// to the scope it actually verified (see #1803's own comment thread).
#[test]
fn test_select_and_materialize_agree_on_corruption_1645() -> Result<()> {
    let decode_failure_err = "invalid escape sequence";
    let structural_err = "unexpected character";
    let collision_err = "ambiguous";

    let cases = [
        (
            "decode failure, top level",
            r#"{"bad": "\x", "keep": 5}"#,
            decode_failure_err,
        ),
        (
            "decode failure, nested in array",
            r#"{"bad": ["\x"], "keep": 5}"#,
            decode_failure_err,
        ),
        (
            "decode failure, nested in object",
            r#"{"bad": {"x": "\x"}, "keep": 5}"#,
            decode_failure_err,
        ),
        (
            "structural error, top level",
            r#"{"bad": xyz123, "keep": 5}"#,
            structural_err,
        ),
        (
            "structural error, nested in array",
            r#"{"bad": [xyz123], "keep": 5}"#,
            structural_err,
        ),
        (
            "structural error, nested in object",
            r#"{"bad": {"x": xyz123}, "keep": 5}"#,
            structural_err,
        ),
        (
            "#1642 colliding decode-failure keys",
            r#"{"bad": {"\ud800":1,"\ud800":2}, "keep": 5}"#,
            collision_err,
        ),
    ];

    for (label, doc, expect_stderr) in cases {
        assert_jq_raises(
            label,
            "select(.bad)",
            &[],
            "select(.bad) | .keep",
            doc,
            5,
            expect_stderr,
        );
        assert_jq_raises(label, "-Sc .bad", &["-Sc"], ".bad", doc, 5, expect_stderr);
        assert_jq_raises(
            label,
            "-e .bad (cursor_to_owned_at_depth, lazy.rs)",
            &["-e"],
            ".bad",
            doc,
            5,
            expect_stderr,
        );
    }
    Ok(())
}

/// One level of container nesting between `.bad` and the malformed leaf, for
/// [`fuzz_select_and_materialize_agree_on_corruption_1965`]'s generated
/// documents -- `Array`/`Object` mirror the two shapes
/// [`test_select_and_materialize_agree_on_corruption_1645`]'s hand-picked
/// cases already cover at depth 1, generalized here to an arbitrary,
/// generated depth and mix.
#[derive(Debug, Clone, Copy)]
enum FuzzContainer {
    Array,
    Object,
}

/// The three malformation kinds [`test_select_and_materialize_agree_on_corruption_1645`]'s
/// fixed case list covers, as a generatable enum.
#[derive(Debug, Clone, Copy)]
enum FuzzMalformation {
    DecodeFailure,
    StructuralError,
    Collision,
}

impl FuzzMalformation {
    /// The JSON text substituted at the leaf position -- a raw malformed
    /// *value* for the first two kinds, a whole malformed *object* (two
    /// colliding decode-failure keys, #1642) for the third, since a
    /// collision isn't expressible as a single scalar value.
    fn leaf_json(self) -> &'static str {
        match self {
            Self::DecodeFailure => r#""\x""#,
            Self::StructuralError => "xyz123",
            Self::Collision => r#"{"\ud800":1,"\ud800":2}"#,
        }
    }

    /// The stderr substring every one of the three CLI paths must raise,
    /// matching [`test_select_and_materialize_agree_on_corruption_1645`]'s
    /// own three constants -- stable across nesting depth/shape, since the
    /// underlying `EvalError`'s message never mentions its own position.
    fn expect_stderr(self) -> &'static str {
        match self {
            Self::DecodeFailure => "invalid escape sequence",
            Self::StructuralError => "unexpected character",
            Self::Collision => "ambiguous",
        }
    }
}

/// Wrap `leaf` in `path`'s containers, outermost first -- `path = []` leaves
/// `leaf` unwrapped (depth-0, matching the existing "top level" case);
/// `path = [Array]`/`[Object]` reproduce the existing "nested in
/// array"/"nested in object" cases exactly for `DecodeFailure`/
/// `StructuralError` (the only two the hand-picked list ever nested); the
/// hand-picked list's `Collision` case was top-level only, so any nested
/// `Collision` path here is new coverage, not a reproduction. Longer paths
/// generate depths the hand-picked list never covered for any kind.
fn fuzz_wrap_json(path: &[FuzzContainer], leaf: &str) -> String {
    match path.split_first() {
        None => leaf.to_string(),
        Some((FuzzContainer::Array, rest)) => format!("[{}]", fuzz_wrap_json(rest, leaf)),
        Some((FuzzContainer::Object, rest)) => {
            format!(r#"{{"x": {}}}"#, fuzz_wrap_json(rest, leaf))
        }
    }
}

fn fuzz_build_json_doc(path: &[FuzzContainer], malformation: FuzzMalformation) -> String {
    format!(
        r#"{{"bad": {}, "keep": 5}}"#,
        fuzz_wrap_json(path, malformation.leaf_json())
    )
}

// Differential fuzzer for #1965: generalizes
// `test_select_and_materialize_agree_on_corruption_1645`'s hand-picked
// 7-case list (3 malformation kinds x up to 2 nesting depths) to
// proptest-generated nesting paths of 0-4 arbitrary `Array`/`Object`
// containers, crossed with all 3 malformation kinds -- the same "generate
// nesting depth/shape, run the same CLI battery, assert consistency" design
// the issue asked for, so a divergence at a depth/shape combination the
// fixed list never happened to hit still gets caught. Kept alongside
// (rather than replacing) the fixed-case test: the fixed list's exact case
// labels are easier to read in a failure message, and losing that
// human-readable coverage while adding generated coverage would be a
// regression in debuggability, not just redundant.
//
// `ProptestConfig::with_cases` is turned down from proptest's own default
// (256) because this drives three real subprocess spawns per case (a
// `Command::new(env!("CARGO_BIN_EXE_succinctly"))` per
// `run_jq_full`/`assert_jq_raises` call, unlike proptest's usual in-process
// property) -- 48 cases x 3 spawns is already ~3x this file's entire
// pre-existing corruption-consistency coverage in one property.
proptest! {
    #![proptest_config(ProptestConfig::with_cases(48))]

    #[test]
    fn fuzz_select_and_materialize_agree_on_corruption_1965(
        path in prop::collection::vec(
            prop_oneof![Just(FuzzContainer::Array), Just(FuzzContainer::Object)],
            0..=4,
        ),
        malformation in prop_oneof![
            Just(FuzzMalformation::DecodeFailure),
            Just(FuzzMalformation::StructuralError),
            Just(FuzzMalformation::Collision),
        ],
    ) {
        let doc = fuzz_build_json_doc(&path, malformation);
        let expect_stderr = malformation.expect_stderr();
        let label = format!("{path:?}/{malformation:?}");

        assert_jq_raises(&label, "select(.bad)", &[], "select(.bad) | .keep", &doc, 5, expect_stderr);
        assert_jq_raises(&label, "-Sc .bad", &["-Sc"], ".bad", &doc, 5, expect_stderr);
        assert_jq_raises(
            &label,
            "-e .bad (cursor_to_owned_at_depth, lazy.rs)",
            &["-e"],
            ".bad",
            &doc,
            5,
            expect_stderr,
        );
    }
}

#[test]
fn test_builtin_type() -> Result<()> {
    let (output, code) = run_jq_stdin("type", r#"{"a":1}"#, &["-r"])?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), "object");
    Ok(())
}

