/// #1702 fixed `del(.)`/`del(.?)` to emit nothing / no-op in yq mode; confirm
/// `succinctly jq` still follows real jq's own model unchanged — both
/// produce `null` on any target.
#[test]
fn test_jq_mode_root_del_still_null_after_1702() -> Result<()> {
    for expr in ["del(.)", "del(.?)"] {
        let (stdout, stderr, code) = run_jq_full(&["-c", expr], Some(r#"{"a":1}"#))?;
        assert_eq!(stdout.trim(), "null", "expr={expr} stderr: {stderr:?}");
        assert_eq!(code, 0, "expr={expr} stderr: {stderr:?}");
    }
    Ok(())
}

// =============================================================================
// #1428: autovivification must not outlive a write that never happens
// =============================================================================

/// Walking to a write target autovivifies every missing step on the way, but
/// an `Iterate` over the `Null` that creates has no elements to assign to, so
/// the write never happens and the fabricated chain was left behind. jq treats
/// path collection as read-only until a write is confirmed.
///
/// Every expectation here is the pinned jq 1.7.1's own output.
#[test]
fn test_suppressed_write_leaves_no_autovivified_chain_1428() -> Result<()> {
    for (input, filter, expected) in [
        // The issue's own repros.
        ("null", ".a[]? = 9", "null\n"),
        ("[1,2,3]", ".[5][]?[0] = 9", "[1,2,3]\n"),
        ("null", ".a.b[]?[0] = 9", "null\n"),
        // An *existing* object must not gain the key either.
        ("{}", ".a[]? = 9", "{}\n"),
        // Depth is not special: nothing at any level survives.
        ("null", ".a.b.c[]? = 9", "null\n"),
        // A tail after the iterate behaves the same.
        ("null", ".a[]?.b = 9", "null\n"),
        ("null", ".a[]?.b[]? = 9", "null\n"),
        // `|=` shares the walker and the bug.
        ("null", ".a[]? |= .+1", "null\n"),
        ("{}", ".a[]? |= .+1", "{}\n"),
        ("null", ".a[]?.b |= 9", "null\n"),
        // ...and so do the compound operators built on it.
        ("null", ".a[]? += 1", "null\n"),
        // The probe's out-of-range *index* branch: the array exists, so the
        // walk gets that far, but the index is past its end -- which is a slot
        // `write_index` would pad into existence, i.e. "would create". Padding
        // it and then discovering the iterate writes nothing is exactly the
        // stranding this fix removes, here as trailing `null`s rather than a
        // fabricated key.
        ("{\"a\":[1]}", ".a[5][]? = 9", "{\"a\":[1]}\n"),
        ("{\"a\":[1]}", ".a[5][]? |= 9", "{\"a\":[1]}\n"),
        ("{\"a\":[1]}", ".a[5].b[]? = 9", "{\"a\":[1]}\n"),
        ("[1]", ".[5][]? = 9", "[1]\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }
    Ok(())
}

/// The other half of #1428, and the reason a naive "never autovivify" fix is
/// wrong: a `?`-suppressed write that *does* happen still creates its chain.
#[test]
fn test_confirmed_write_still_autovivifies_1428() -> Result<()> {
    for (input, filter, expected) in [
        // `?` on a step that resolves: the write lands, so the chain stays.
        ("null", ".a[0]? = 9", "{\"a\":[9]}\n"),
        ("null", ".a?.b = 9", "{\"a\":{\"b\":9}}\n"),
        // No `?` at all -- ordinary autovivification, untouched.
        ("null", ".a = 9", "{\"a\":9}\n"),
        ("null", ".a.b = 9", "{\"a\":{\"b\":9}}\n"),
        ("null", ".a[2] |= 9", "{\"a\":[null,null,9]}\n"),
        // A real iterate target writes to every element.
        ("{\"a\":[1,2]}", ".a[]? = 9", "{\"a\":[9,9]}\n"),
        ("{\"a\":{\"k\":1}}", ".a[]? = 9", "{\"a\":{\"k\":9}}\n"),
        // An empty container is a legitimate zero-element write, and the key
        // already exists, so the document is unchanged either way.
        ("{\"a\":[]}", ".a[]? = 9", "{\"a\":[]}\n"),
        // A slice write on a missing parent genuinely writes -- it must not be
        // skipped along with the iterate cases.
        ("null", ".a[0:1]? = [9]", "{\"a\":[9]}\n"),
        // One path writing and another not, in a single assignment.
        ("null", "(.a[]?, .b) = 9", "{\"b\":9}\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }
    Ok(())
}

/// #1428 must not turn a genuine error into a silent no-op. The first version
/// of the fix did exactly that -- reporting "absent" for a wrong-type
/// container let the walker skip errors jq still raises, 59 of them across a
/// differential sweep.
///
/// The distinction that matters: a `?` binds to the component it is written
/// on. In `[] | .a[]? = 9` it is on the *iterate*, so the `.a`-on-an-array
/// type error is still raised.
#[test]
fn test_suppressed_write_still_raises_real_type_errors_1428() -> Result<()> {
    for (input, filter, needle) in [
        ("[]", ".a[]? = 9", "Cannot index array with string"),
        ("5", ".a[]? = 9", "Cannot index number with string"),
        ("\"s\"", ".a.b[]? = 9", "Cannot index string with string"),
        ("true", ".a[]?[0] = 9", "Cannot index boolean with string"),
        (
            "{\"a\":1}",
            ".a.b[]? = 9",
            "Cannot index number with string",
        ),
        ("{}", ".[5][]?[0] = 9", "Cannot index object with number"),
        // No `?` anywhere: iterating a null still raises, and the document is
        // never emitted, so nothing can be left fabricated in it.
        ("null", ".a[] = 9", "Cannot iterate over null"),
    ] {
        let (_, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_ne!(code, 0, "{input} | {filter} must fail");
        assert!(
            stderr.contains(needle),
            "{input} | {filter} -- want {needle:?}, got {stderr}"
        );
    }

    // A `?` on an *earlier* component cancels the whole write, and must not be
    // mistaken for "the parent is missing, go probe the tail" -- doing so
    // manufactured a `Cannot iterate over null` that jq never raises (this is
    // #1298's own case, which caught the second wrong version of this fix).
    let (stdout, stderr, code) = run_jq_full(&["-c", ".a?.b[].c = 9"], Some("5"))?;
    assert_eq!(code, 0, "stderr={stderr}");
    assert_eq!(stdout, "5\n");
    Ok(())
}

/// #1428 review follow-up: a write whose *value* is `null` is still a write.
///
/// The first two versions of this fix inferred "nothing was written" from "the
/// target is still `Null`", which is indistinguishable from a legitimate `null`
/// write. `null | (.a|.) = null` dropped to `null` where jq (and yq) keep
/// `{"a":null}` -- 56 distinct filter shapes regressed this way, none of them
/// covered by the suite, because they all need an explicit `|` inside the path
/// to produce an `Identity`-shaped tail.
///
/// The guard is now structural: it applies only where the deciding component
/// is an `Iterate`, which over a freshly-created `Null` writes nothing *by
/// construction* -- no inspection of the resulting value required.
#[test]
fn test_null_valued_write_is_still_a_write_1428() -> Result<()> {
    for (input, filter, expected) in [
        ("null", "(.a|.) = null", "{\"a\":null}\n"),
        ("null", "(.a|.) = .x", "{\"a\":null}\n"),
        ("null", "(.a|.b) = null", "{\"a\":{\"b\":null}}\n"),
        ("null", "(.a|.) |= null", "{\"a\":null}\n"),
        ("null", "(.a|.) |= .", "{\"a\":null}\n"),
        ("null", "(.a|.) //= null", "{\"a\":null}\n"),
        ("null", "(.a|.) += null", "{\"a\":null}\n"),
        ("null", "(.a[0]|.) |= null", "{\"a\":[null]}\n"),
        (
            "null",
            "(.[5]|.) = null",
            "[null,null,null,null,null,null]\n",
        ),
        // A plain terminal write of `null` was never at risk, but pins the
        // pair: the paren form above and this one must agree.
        ("null", ".a = null", "{\"a\":null}\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }
    Ok(())
}

/// #1428 review follow-up: the `|=` walker recurses one component at a time, so
/// a frame two or more levels above the iterate has to undo its own slot too.
///
/// Checking only the head of the remaining path left `null | .a.b[]? |= 9` as
/// `{"a":{}}` -- the inner frame correctly removed `.b`, but `.a` was then an
/// empty object rather than the `Null` it started as, so the outer frame could
/// not tell. 40 (input, filter) pairs were still wrong at that point.
#[test]
fn test_nested_suppressed_update_unwinds_every_level_1428() -> Result<()> {
    for (input, filter) in [
        ("null", ".a.b[]? |= 9"),
        ("null", ".a.b[]? |= null"),
        ("null", ".a.b[]? += 1"),
        ("null", ".a.b.c[]? |= 9"),
        ("null", ".a.b.c.d[]? |= 9"),
        ("null", ".a.b.c[]? //= null"),
        ("{}", ".a.b[]? |= 9"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, format!("{input}\n"), "{input} | {filter}");
    }
    Ok(())
}

/// #1428 review follow-up: a slice can be a *read-through* step whose own tail
/// declines to write, and then the chain built to reach it is stranded exactly
/// like the plain iterate case.
///
/// This class was reached only after the guard started making tails legitimately
/// write nothing: `through_slice`'s `Null` arm then saw an unwritten `Null` and
/// raised its write-time "A slice of an array can only be assigned another
/// array", turning a document jq leaves alone into a hard exit-5 failure. The
/// arm now distinguishes the two using `terminal_write`, which exists for
/// exactly that question -- when the edit *is* the write, a `Null` result means
/// the RHS was `null`, and `null | .[0:1] = null` does still raise.
#[test]
fn test_read_through_slice_that_writes_nothing_is_a_noop_1428() -> Result<()> {
    for (input, filter, expected) in [
        ("null", ".[0:1][0][]? = 9", "null\n"),
        ("null", ".[0:1][0][]? |= 9", "null\n"),
        ("null", ".[0:1][0][]? += 1", "null\n"),
        ("null", ".a[0:1][0][]? = 9", "null\n"),
        // The slice immediately followed by an iterate -- filed as #1873 while
        // it was still failing, and closed by this same fix.
        ("null", ".a[0:1][]? = 9", "null\n"),
        ("{}", ".a[0:1][]? = 9", "{}\n"),
        ("null", ".[0:1][]? = 9", "null\n"),
        // An existing `null` parent is untouched either way.
        ("{\"a\":null}", ".a[0:1][]? = 9", "{\"a\":null}\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }

    // A slice write that *does* write still builds its chain...
    for (input, filter, expected) in [
        ("null", ".a[0:1] = [9]", "{\"a\":[9]}\n"),
        ("null", ".[0:1] = [9]", "[9]\n"),
        ("null", ".a[0:1][0] = 9", "{\"a\":[9]}\n"),
        ("null", ".a[0:1]? = [9]", "{\"a\":[9]}\n"),
        ("[1,2,3]", ".[0:2] = [9]", "[9,3]\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }

    // ...and a terminal slice assignment of a non-array still raises, which is
    // what keeps the `terminal_write` distinction honest.
    for filter in [".[0:1] = null", ".[0:1] = 9"] {
        let (_, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_ne!(code, 0, "{filter} must raise");
        assert!(
            stderr.contains("slice of an array"),
            "{filter} -- got {stderr}"
        );
    }
    Ok(())
}

/// #1428 review follow-up: `update_path`'s slice arm must compute
/// `terminal_write`, not hardcode `false`.
///
/// `set_path`'s slice arm has always derived it from its tail. `update_path`'s
/// hardcoded `false` was harmless while `through_slice`'s `Null` arm treated
/// every unwritten `Null` as an error -- but once that arm learned to no-op for
/// a genuine read-through, the wrong flag made it swallow the real error for a
/// filter that writes `null` directly to the slice.
#[test]
fn test_slice_update_with_identity_tail_still_raises_1428() -> Result<()> {
    for (input, filter) in [
        ("null", "(.a[0:1]|.) |= null"),
        ("{\"a\":null}", "(.a[0:1]|.) |= null"),
        ("null", "(.[0:1]|.) |= null"),
        ("null", "(.a[0:1]|.) |= 9"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_ne!(code, 0, "{input} | {filter} must raise, got {stdout:?}");
        assert!(
            stderr.contains("slice of an array"),
            "{input} | {filter} -- got {stderr}"
        );
    }

    // The read-through spelling of the same shape still no-ops, which is the
    // distinction `terminal_write` draws.
    for (input, filter, expected) in [
        ("null", ".a[0:1][]? |= 9", "null\n"),
        ("null", ".a[0:1][0][]? |= 9", "null\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }
    Ok(())
}

/// #1876/#1883: `through_slice`'s `OwnedValue::String` *terminal-write* arm
/// used to refuse with the generic `Cannot update string slices` message
/// immediately, without ever running the update filter -- unlike its
/// `!terminal_write` sibling just above it (and every other arm in this
/// function), which always runs `edit` first. This discarded the filter's
/// own side effects (`debug`/`stderr`) and swallowed its own genuine errors
/// (an explicit `error(...)` call, or an arithmetic type error from `+=`/
/// `-=`) behind the generic refusal instead of letting them propagate --
/// confirmed live against jq 1.7.1 for all three repros below.
#[test]
fn test_string_slice_terminal_write_runs_edit_before_refusing_1876_1883() -> Result<()> {
    // `debug`'s stderr side effect still fires even though the write is
    // ultimately refused -- both jq and succinctly print the debug line
    // (with the *sliced* substring "he", proving `edit` really ran against
    // the throwaway substring rather than the whole original string), then
    // refuse with the same generic message.
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:2] |= (debug|9)"], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(
        stderr.starts_with("[\"DEBUG:\",\"he\"]\n"),
        "stderr: {stderr}"
    );
    assert!(
        stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // An explicit `error(...)` inside the update filter propagates as
    // itself, not as the generic string-slice refusal.
    let (stdout, stderr, code) =
        run_jq_full(&["-c", ".[0:2] |= error(\"boom\")"], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(stderr.contains("boom"), "stderr: {stderr}");
    assert!(
        !stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // `+=`/`-=`'s own arithmetic type error surfaces instead of the generic
    // refusal (#1883's own repro).
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:1] += 1"], Some("\"s\""))?;
    assert_ne!(code, 0);
    assert!(stderr.contains("cannot be added"), "stderr: {stderr}");
    assert!(
        !stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:1] -= 1"], Some("\"s\""))?;
    assert_ne!(code, 0);
    assert!(stderr.contains("cannot be subtracted"), "stderr: {stderr}");
    assert!(
        !stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // Control: when the update filter succeeds with an ordinary value, the
    // write is still refused with the generic message (the refusal itself
    // is correct jq behavior -- only the *ordering* relative to `edit`
    // changed).
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:1] = \"X\""], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    Ok(())
}

/// #1894: `through_slice`'s `OwnedValue::Array`/`OwnedValue::String`
/// terminal-write arms didn't special-case an update filter that produced
/// no output at all (`|= empty`). Real jq's `_modify` falls back to
/// `delpaths` when the update filter yields nothing, and deleting a
/// slice-shaped path removes that whole range -- for an array that's
/// exactly "splice in nothing"; for a string, jq raises a different
/// sentence than a non-empty write does. Every case confirmed live against
/// jq 1.7.1.
#[test]
fn test_slice_delete_on_empty_update_filter_1894() -> Result<()> {
    // Array: the sliced range is spliced out, shrinking the array.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[0:2] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[3]");

    // String: a different message than a non-empty string-slice write.
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:2] |= empty"], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("Cannot delete fields from string"),
        "stderr: {stderr}"
    );
    assert!(
        !stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // `?` does not suppress this -- it's a write-time application error,
    // not a navigation failure, confirmed live.
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:2]? |= empty"], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("Cannot delete fields from string"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // Control: a literal `null` write (not an empty filter) still raises
    // the pre-existing, unaffected error -- the fix distinguishes "no
    // output" from "output is null".
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:2] |= null"], Some("[1,2,3]"))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("A slice of an array can only be assigned another array"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    Ok(())
}

/// #1877: a *nested* terminal slice (reached through another slice, or
/// through an inline `?`) with `|= empty` used to raise "A slice of an
/// array can only be assigned another array" on a `null`/absent target,
/// where real jq leaves the whole document untouched -- confirmed live
/// against jq 1.7.1. This is the same `|= empty` delete/no-op mechanism as
/// #1894, just for the case where nothing exists yet to delete from.
#[test]
fn test_nested_slice_delete_on_empty_update_filter_noops_on_null_1877() -> Result<()> {
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".a[0:1][0:2]? |= empty"], Some("null"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "null");

    // Two slices chained directly (no `?`, no absent field) on an existing
    // array -- the inner slice's own delete-and-splice composes correctly
    // with the outer one's.
    let (stdout, _stderr, code) =
        run_jq_full(&["-c", "(.[0:3] | .[0:1]) |= empty"], Some("[1,2,3,4,5]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[2,3,4,5]");

    // A slice followed by a plain `Index` (not another slice) -- #1916
    // closed the general "`.a |= empty` should delete the key/element, not
    // write `null`" gap for `Field`/`Index`, so this now deletes the
    // element too, matching jq's own answer, rather than the `[null,2,3,4]`
    // this assertion recorded before that fix landed.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[0:2][0] |= empty"], Some("[1,2,3,4]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[2,3,4]");

    Ok(())
}

/// #1916: an update filter that produces no output at all deletes the
/// key/element it targets, rather than leaving it `null` -- jq's `_modify`
/// falls back to `delpaths` here (the same mechanism #1877/#1894 already
/// gave `through_slice`'s slice arms). Every expected value below is real
/// jq 1.7.1's own output, captured live.
#[test]
fn test_field_index_iterate_delete_on_empty_update_filter_1916() -> Result<()> {
    // Field: the key disappears entirely, not `"a":null`.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".a |= empty"], Some(r#"{"a":1,"b":2}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"b":2}"#);

    // Index: the element is removed, the array shrinks.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[0] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[2,3]");

    // Iterate over an array: every element that updates to nothing is
    // dropped.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[]");

    // Iterate over an object: same, keyed by name.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[] |= empty"], Some(r#"{"a":1,"b":2}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "{}");

    // Out-of-range positive/negative indices stay a true no-op: nothing
    // was ever really there to delete, so nothing is padded in either.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[5] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[1,2,3]");
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[-5] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[1,2,3]");

    // The bounds check on a *real* write still fires -- it lives on the
    // write path, not the delete path an empty filter takes instead.
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[-5] |= 99"], Some("[1,2,3]"))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("Out of bounds negative array index"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // An autovivified container that ends up with nothing written into it
    // reverts to `null` rather than surfacing as an artifact of the
    // attempt (`{}`/`[]`).
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".a |= empty"], Some("null"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "null");
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[0] |= empty"], Some("null"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "null");

    // Nested: only the reached leaf is deleted, ancestors that already
    // existed are left in place.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".a.b |= empty"], Some(r#"{"a":{"b":1}}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"a":{}}"#);

    Ok(())
}

/// #1653: `--unbuffered` must actually interleave stdout and stderr in real
/// time, not merely flush a batch that was already fully evaluated.
///
/// Every expected string here is jq 1.7.1's own combined output, captured
/// live. The property is *ordering*, so these assert on one merged stream
/// (`run_jq_interleaved`) -- separately-captured pipes would pass even with
/// the batching bug, since each stream's own contents were always correct.
///
/// The `-n` and `--slurp` forms are the routes this fix streams; a document
/// read on the M2 lazy path is deliberately not asserted here (see
/// `test_streamed_ordering_not_yet_reached_on_m2_path_1653`).
#[test]
fn test_unbuffered_interleaves_stdout_and_stderr_1653() -> Result<()> {
    // (args, stdin, combined stdout+stderr, exit code) -- all four captured
    // live from jq 1.7.1, byte for byte.
    for (args, input, expected, expected_code) in [
        // The issue's own repro: `1` is written before `debug` is evaluated.
        (
            vec!["--unbuffered", "-cn", "1, debug, 2"],
            None,
            "1\n[\"DEBUG:\",null]\nnull\n2\n",
            0,
        ),
        // An uncaught error is a side effect with the same ordering rule:
        // the outputs that preceded it are already on stdout.
        (
            vec!["--unbuffered", "-cn", "1, error(\"x\"), 3"],
            None,
            "1\njq: error (at <unknown>): x\n",
            5,
        ),
        // `halt_error` writes its payload after the earlier output. A
        // *number* payload is written as JSON with a trailing newline (a
        // string payload is the raw, newline-less case) -- captured from
        // jq, not assumed.
        (
            vec!["--unbuffered", "-cn", "1, (2|halt_error), 3"],
            None,
            "1\n2\n",
            5,
        ),
        // `stderr` echoes its input without a trailing newline, so the
        // interleaving is visible as `null` butting against the next line.
        (
            vec!["--unbuffered", "-cn", "1, stderr, 2"],
            None,
            "1\nnullnull\n2\n",
            0,
        ),
        // Per-element, through a pipe: each element's stdout write lands
        // before the next element is evaluated at all.
        (
            vec!["--unbuffered", "-cn", "range(3) | (., debug)"],
            None,
            "0\n[\"DEBUG:\",0]\n0\n1\n[\"DEBUG:\",1]\n1\n2\n[\"DEBUG:\",2]\n2\n",
            0,
        ),
        // `--slurp` reaches the same streaming path.
        (
            vec!["--unbuffered", "-c", "--slurp", "1, debug, 2"],
            Some("{}"),
            "1\n[\"DEBUG:\",[{}]]\n[{}]\n2\n",
            0,
        ),
        // So does the input-queue bridge (`inputs`), which streams through
        // `eval_each_owned` rather than collecting first.
        (
            vec!["--unbuffered", "-cn", "inputs, debug"],
            Some("1\n2\n"),
            "1\n2\n[\"DEBUG:\",null]\nnull\n",
            0,
        ),
        // `-S` forces materialization and so routes here too -- one of four
        // flags (`-S`, `-a`, `-R`, `--seq`) this fix reaches that the first
        // draft of the compliance note failed to list.
        (
            vec!["--unbuffered", "-c", "-S", "1, debug, 2"],
            Some("{}"),
            "1\n[\"DEBUG:\",{}]\n{}\n2\n",
            0,
        ),
    ] {
        let (combined, code) = run_jq_interleaved(&args, input)?;
        assert_eq!(combined, expected, "args {args:?} input {input:?}");
        // The exit code is pinned alongside the bytes rather than derived
        // from them: it is part of the captured behaviour for the
        // `error(...)`/`halt_error` rows.
        assert_eq!(code, expected_code, "exit code for {args:?}");
    }
    Ok(())
}

/// #1653: the M2 lazy path (a document read from stdin/a file) still batches.
///
/// Pinned deliberately rather than left untested. Streaming it means routing
/// the CLI's default path through the demand-driven evaluator, and
/// `each_lazy_keys_iterate_sink` there skips the #1194 malformed-key check
/// that #1629 added specifically so bare `keys_unsorted[]` *would* raise --
/// a gap #1770 closed as an accepted trade for early-exit consumers like
/// `first(...)`, not one that may be universalized to the default path.
/// Routing M2 through it was tried and reverted: it regressed six tests
/// across #1642/#1629/#1770's undecodable-key handling.
///
/// When that is resolved, this test should start failing -- at which point
/// the expectation becomes jq's own
/// `["DEBUG:",1]\n1\n["DEBUG:",2]\n2\n` and it moves into the test above.
#[test]
fn test_streamed_ordering_not_yet_reached_on_m2_path_1653() -> Result<()> {
    let (combined, code) = run_jq_interleaved(&["--unbuffered", "-c", ".[]|debug"], Some("[1,2]"))?;
    assert_eq!(code, 0);
    assert_eq!(
        combined, "[\"DEBUG:\",1]\n[\"DEBUG:\",2]\n1\n2\n",
        "M2 path still batches; see this test's doc comment"
    );
    Ok(())
}

/// #1653: the streaming path's own `--input-dsv` row loop, including the
/// `-e` branch that materializes each row's last output.
///
/// `--input-dsv` was a fifth `evaluate_input` call site the first pass at
/// #1653 missed, so it kept batching after every other route streamed; these
/// pin both that it streams and that `-e` still reports row truthiness.
#[test]
fn test_dsv_rows_stream_and_track_exit_status_1653() -> Result<()> {
    let dir = std::env::temp_dir().join(format!("sjq-dsv-1653-{}", std::process::id()));
    std::fs::create_dir_all(&dir)?;
    let csv = dir.join("rows.csv");
    std::fs::write(&csv, "a,b\n1,2\n")?;
    let path = csv.to_str().expect("temp path is utf-8");

    // Each row's output is written before the next row is evaluated, so the
    // per-row `debug` lands *after* that row's own `1`, not before both rows.
    let (combined, code) = run_jq_interleaved(
        &[
            "--unbuffered",
            "-c",
            "--input-dsv",
            ",",
            "1, debug, 2",
            path,
        ],
        None,
    )?;
    assert_eq!(
        combined,
        "1\n[\"DEBUG:\",[\"a\",\"b\"]]\n[\"a\",\"b\"]\n2\n\
         1\n[\"DEBUG:\",[\"1\",\"2\"]]\n[\"1\",\"2\"]\n2\n"
    );
    assert_eq!(code, 0);

    // `-e` on the same path: the last output drives the exit code.
    let (out, _err, code) = run_jq_full(&["-c", "-e", "--input-dsv", ",", ".[0]", path], None)?;
    assert_eq!(out, "\"a\"\n\"1\"\n");
    assert_eq!(code, 0);
    let (_out, _err, code) = run_jq_full(&["-c", "-e", "--input-dsv", ",", "null", path], None)?;
    assert_eq!(code, 1, "a null last output is jq's falsy exit");

    let _ = std::fs::remove_dir_all(&dir);
    Ok(())
}

/// #1653: a `LazySeq` item that fails while being materialized on the
/// streaming path still reports through `sink`, for each control it can
/// raise.
///
/// `map(f)` stays lazy until this boundary forces it, so `f`'s own
/// error/halt surfaces here rather than during evaluation -- the one arm of
/// `materialize_stream_item` that handles a control at all (every other
/// control is the `Flow`'s outcome, reported by the caller).
#[test]
fn test_streamed_lazy_seq_materialization_control_1653() -> Result<()> {
    for (filter, expected_out, expected_code, expected_err) in [
        ("[1,2]|map(.+1)", "[2,3]\n", 0, ""),
        (
            "[1,0]|map(1/.)",
            "",
            5,
            "number (1) and number (0) cannot be divided because the divisor is zero",
        ),
        (
            "[1,2]|map(if .==2 then halt_error(3) else . end)",
            "",
            3,
            "2",
        ),
    ] {
        let (out, err, code) = run_jq_full(&["--slurp", "-c", filter], Some("{}"))?;
        assert_eq!(out, expected_out, "stdout for {filter}");
        assert_eq!(code, expected_code, "exit for {filter} -- stderr={err}");
        if expected_err.is_empty() {
            assert_eq!(err, "", "stderr for {filter}");
        } else {
            assert!(
                err.contains(expected_err),
                "stderr for {filter}: got {err:?}"
            );
        }
    }
    Ok(())
}

/// #1723: one RFC 7464 record can hold more than one JSON value, and real jq
/// emits every one of them.
///
/// `succinctly jq --seq` used to drop such a record **in full**, exit 0 --
/// silent data loss on a record real jq reads fine, not the missing-warning
/// gap #1723 was filed as. The cause was `seq_record_parses` validating the
/// whole record as a single value, so `1 2` looked malformed.
///
/// Every expectation captured from jq 1.7.1.
#[test]
fn test_seq_record_with_multiple_values_emits_all_1723() -> Result<()> {
    for (input, expected) in [
        // Mixed types, whitespace-separated.
        ("\x1e1 \"x\" [2]\n", "1\n\"x\"\n[2]\n"),
        // A newline is just whitespace inside a record -- not a boundary.
        ("\x1e1\n2\n", "1\n2\n"),
        ("\x1enull null\n", "null\nnull\n"),
        ("\x1e\"a\" \"b\"\n", "\"a\"\n\"b\"\n"),
        ("\x1etrue false null\n", "true\nfalse\nnull\n"),
        ("\x1e[1] 2 {\"a\":3}\n", "[1]\n2\n{\"a\":3}\n"),
        ("\x1e{\"a\":1} {\"b\":2}\n", "{\"a\":1}\n{\"b\":2}\n"),
        ("\x1e{} []\n", "{}\n[]\n"),
        ("\x1e-1 -2\n", "-1\n-2\n"),
        ("\x1e1  2\n", "1\n2\n"),
        // Multi-value records interleave with ordinary single-value ones.
        ("\x1e1 2\n\x1e3\n", "1\n2\n3\n"),
        // The leading-zero retry (#1243) still applies, in either position.
        ("\x1e007e5 1\n", "7E+5\n1\n"),
        ("\x1e1 007e5\n", "1\n7E+5\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?} -- stderr={stderr}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1723: adding multi-value support must not resurrect a value real jq
/// abandons.
///
/// Two rules would have been broken by a naive "emit every value in the
/// record" change, and each is pinned here because the differential sweep
/// caught them as regressions in the first drafts:
///
/// 1. A record's *last* value is dropped when it is a bare number with no
///    terminating byte after it -- jq's incremental number scanner cannot
///    rule out more digits arriving. That rule was already encoded for the
///    stream's final record; it is really per-record, so `\x1e1 2\x1e3`
///    keeps `1` and `3` but drops the `2`, while a single newline after the
///    `2` disambiguates it and all three survive.
/// 2. Input with **no RS byte anywhere** is abandoned wholesale (#1525),
///    however well-formed its content is -- relaxing the trailing-record
///    skip for multi-value records started emitting it.
#[test]
fn test_seq_multivalue_still_drops_what_jq_abandons_1723() -> Result<()> {
    for (input, expected, why) in [
        (
            "\x1e1 2\x1e3\n",
            "1\n3\n",
            "bare number before RS is ambiguous",
        ),
        (
            "\x1e1 2\n\x1e3\n",
            "1\n2\n3\n",
            "a newline disambiguates it",
        ),
        ("\x1e1 2", "1\n", "bare number at EOF is ambiguous"),
        ("\x1e1 2 ", "1\n2\n", "trailing space disambiguates it"),
        (
            "1 2\n",
            "",
            "no RS byte anywhere: whole input abandoned (#1525)",
        ),
        (
            "\x1e1\n\x1e2",
            "1\n",
            "single-value trailing bare number, unchanged",
        ),
        ("\x1e1\n", "1\n", "plain single-value record, unchanged"),
        ("\x1e{\"a\":1\n", "", "malformed record still dropped whole"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?} -- {why}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1723 code review: content before the *first* RS byte is not a record,
/// and real jq discards it however well-formed it is.
///
/// Multi-value support made a pre-existing single-value leak here emit
/// *every* value in that prefix, widening the divergence rather than
/// introducing it -- `"a" "b"\x1e3` printed all three. Both the widened and
/// the original leak are fixed: only `3` survives, as in jq.
#[test]
fn test_seq_discards_content_before_first_rs_byte_1723() -> Result<()> {
    for (input, expected, why) in [
        (
            "\"a\" \"b\"\x1e3\n",
            "3\n",
            "multi-value prefix, widened by #1723",
        ),
        (
            "\"a\"\x1e3\n",
            "3\n",
            "single-value prefix, leaked on main too",
        ),
        ("1 2\x1e3\n", "3\n", "numeric prefix"),
        (
            "1 2\n",
            "",
            "no RS at all: #1525 abandonment still owns this",
        ),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?} -- {why}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1723 code review: the error-location marker a `--seq` value reports.
///
/// Three separate offset defects, none of which any existing test could
/// catch because none assert the `(at file:line)` marker at all:
///
/// - `seq_trailing_record_is_dropped` tested the trailing record's *first
///   byte* for "ambiguous bare number". Before #1723 a record was always one
///   value, so first-byte and last-value were the same question; with
///   multi-value records they differ, and `\x1e1 "a"` reported `<unknown>`
///   where jq names the line.
/// - Non-last values paired ranges taken from the *trimmed* record with the
///   *untrimmed* record's start offset, so leading whitespace shifted the
///   reported line (`\x1e  "a"\n"b"\n`).
/// - Scanning a leading-zero-normalized copy produced ranges shorter than
///   the original, because normalization *deletes* zeros rather than
///   rewriting in place (`\x1e0007\n"b"\n`). Ranges now always index the
///   original text, with normalization applied per value.
#[test]
fn test_seq_value_error_location_marker_1723() -> Result<()> {
    let dir = std::env::temp_dir().join(format!("sjq-seq-1723-{}", std::process::id()));
    std::fs::create_dir_all(&dir)?;
    let file = dir.join("z.json");
    let path = file.to_str().expect("temp path is utf-8");

    for (input, expected_marker, why) in [
        ("\x1e1 \"a\"", "z.json:0", "last value is not a bare number"),
        (
            "\x1e\"a\" 2",
            "<unknown>",
            "last value IS an ambiguous bare number",
        ),
        (
            "\x1e  \"a\"\n\"b\"\n",
            "z.json:2",
            "leading whitespace must not shift the line",
        ),
        (
            "\x1e0007\n\"b\"\n",
            "z.json:2",
            "normalization must not shift the line",
        ),
        ("\x1e\"a\"", "z.json:0", "single value, unchanged"),
        (
            "\x1e1\n\x1e2",
            "<unknown>",
            "single trailing bare number, unchanged",
        ),
    ] {
        std::fs::write(&file, input)?;
        let (_out, stderr, _code) =
            run_jq_full(&["--seq", "-s", "-c", "error(\"x\")", path], None)?;
        let marker = stderr
            .lines()
            .find(|l| l.starts_with("jq: error"))
            .unwrap_or_default();
        assert!(
            marker.contains(expected_marker),
            "input {input:?} -- {why}: expected {expected_marker:?} in {marker:?}"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
    Ok(())
}

/// #1723: `--seq` must never emit a value real jq does not.
///
/// #1914 taught the record reader to split a record into several values,
/// which is right for a cleanly separated record but wrong the moment tokens
/// are *adjacent*: a scanner splits `1-2` into `1` and `-2`, while jq lexes
/// it as one malformed number and prints nothing. That shipped, and it made
/// `succinctly jq --seq` **fabricate output** on 205 of 1500 randomly
/// generated records.
///
/// A first attempt at this issue tried to imitate jq's resync instead
/// (emit the prefix, skip the bad token, continue) and fabricated *more*,
/// because jq's `--seq` reader is a streaming lexer/parser with error
/// recovery and a token scanner cannot imitate one. Requiring whitespace
/// after every token is what makes fabrication structurally impossible: the
/// adjacency a scanner mis-splits is exactly what is now rejected.
///
/// Each row here emits nothing, matching jq. Before this fix every one of
/// them emitted values.
#[test]
fn test_seq_adjacent_tokens_never_fabricate_1723() -> Result<()> {
    for (input, why) in [
        ("\x1e1-2\n", "one malformed number, not `1` and `-2`"),
        ("\x1e1null\n", "not `1` and `null`"),
        ("\x1e12true\n", "not `12` and `true`"),
        ("\x1etrue1\n", "not `true` and `1`"),
        (
            "\x1e5-3 7\n",
            "must not print `-3` out of the middle of a bad token",
        ),
        ("\x1e1.5true\n", "a fractional number is no different"),
        ("\x1e0007null\n", "nor is a leading-zero one"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, "", "input {input:?} -- {why}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1723: the cost of never fabricating is that a record jq can *partially*
/// read is dropped whole.
///
/// Recorded as a test, not just prose, so the divergence is visible and its
/// direction is pinned: succinctly's output is always a subset of jq's here,
/// never a superset. Reaching jq's own answer needs its incremental parser's
/// failure classification, which is what #1723 still tracks.
#[test]
fn test_seq_partially_readable_record_is_dropped_whole_1723() -> Result<()> {
    for (input, jq_would_emit) in [
        ("\x1e1 {invalid\n", "1"),
        ("\x1e1,2\n", "2"),
        ("\x1e} 5\n", "5"),
        ("\x1e{\"a\":1} xyz\n", "{\"a\":1}"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(
            stripped, "",
            "input {input:?}: dropped whole; real jq emits {jq_would_emit}"
        );
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1723: a record that *ends* unresolved leaves real jq with no EOF
/// position, even when it yielded values first.
///
/// `\x1e"a" 2` emits `"a"` and still reports `<unknown>`, because its
/// trailing `2` never resolved. Defining "dropped" as "yielded nothing"
/// instead got this backwards and broke #1542's own location test — pinned
/// here so the two questions cannot be conflated again.
#[test]
fn test_seq_trailing_unresolved_still_reports_unknown_1723() -> Result<()> {
    let dir = std::env::temp_dir().join(format!("sjq-seq-unres-{}", std::process::id()));
    std::fs::create_dir_all(&dir)?;
    let file = dir.join("z.json");
    let path = file.to_str().expect("temp path is utf-8");

    for (input, expected_marker, why) in [
        (
            "\x1e\"a\" 2",
            "<unknown>",
            "yields \"a\", but ends unresolved",
        ),
        ("\x1e1 \"a\"", "z.json:0", "ends resolved"),
        ("\x1e\"a\"", "z.json:0", "single resolved value"),
        ("\x1e1", "<unknown>", "single unresolved bare number"),
        ("\x1e{\"a\":1", "<unknown>", "unterminated container"),
    ] {
        std::fs::write(&file, input)?;
        let (_out, stderr, _code) =
            run_jq_full(&["--seq", "-s", "-c", "error(\"x\")", path], None)?;
        let marker = stderr
            .lines()
            .find(|l| l.starts_with("jq: error"))
            .unwrap_or_default();
        assert!(
            marker.contains(expected_marker),
            "input {input:?} -- {why}: expected {expected_marker:?} in {marker:?}"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
    Ok(())
}

/// #1928: a self-delimiting token needs no separator after it.
///
/// The first version of this fix required whitespace after *every* token,
/// which dropped records real jq reads fully — a review measured 332 such
/// regressions. A string, object or array carries its own closing
/// delimiter, so adjacency cannot mis-split it; only a number or bare
/// literal is "pending" and genuinely ambiguous.
#[test]
fn test_seq_self_delimiting_tokens_need_no_separator_1928() -> Result<()> {
    for (input, expected) in [
        ("\x1e{\"a\":1}{\"b\":2}\n", "{\"a\":1}\n{\"b\":2}\n"),
        ("\x1e\"a\"\"b\"\n", "\"a\"\n\"b\"\n"),
        ("\x1e[1][2]\n", "[1]\n[2]\n"),
        // A pending token is confirmed by the *start* of a self-delimiting
        // value just as well as by whitespace.
        ("\x1e1[1]\n", "1\n[1]\n"),
        ("\x1e1\"a\"\n", "1\n\"a\"\n"),
        ("\x1e1{\"b\":2}\n", "1\n{\"b\":2}\n"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1928: a bare `true`/`false`/`null` is truncated at an **RS byte** but
/// not at real **EOF** -- unlike a bare number, which is truncated at both.
///
/// | token | at an RS byte | at real EOF |
/// |-------|---------------|-------------|
/// | number (`1`) | abandoned | abandoned |
/// | literal (`true`) | abandoned | **kept** |
/// | string/array/object | kept | kept |
///
/// A number can always take more digits; at EOF jq has seen all the input
/// there will ever be, so a literal is complete. Both halves are pinned
/// because each direction was got wrong once: checking numbers alone left 92
/// shapes emitting a `true` jq drops, and then checking literals at every
/// boundary dropped `printf '\x1etrue'`, which jq prints.
#[test]
fn test_seq_pending_literal_at_boundary_is_truncated_1928() -> Result<()> {
    for (input, expected, why) in [
        // At real EOF a literal is complete -- the half a stricter rule broke.
        ("\x1etrue", "true\n", "bare literal at EOF is kept"),
        ("\x1enull", "null\n", "so is null"),
        ("\x1e\"a\" true", "\"a\"\ntrue\n", "and after another value"),
        ("\x1e{} null", "{}\nnull\n", "likewise"),
        // A number is abandoned at EOF, which is the contrast that makes the
        // rule per-token-kind rather than per-boundary.
        ("\x1e1", "", "a bare number at EOF is still abandoned"),
        (
            "\x1etrue\x1e3\n",
            "3\n",
            "bare literal before RS is abandoned",
        ),
        ("\x1enull\x1e3\n", "3\n", "so is null"),
        ("\x1e5\x1e3\n", "3\n", "as for a bare number, unchanged"),
        ("\x1etrue\n\x1e3\n", "true\n3\n", "a newline confirms it"),
        ("\x1e\"a\"\x1e3\n", "\"a\"\n3\n", "a string self-terminates"),
        ("\x1e[1]\x1e3\n", "[1]\n3\n", "so does an array"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?} -- {why}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// #1473: compile-time function resolution.
//
// Real jq resolves every function call before reading input: an undefined
// function -- or an undefined arity of an existing one -- is a compile error,
// unconditional, uncatchable, exit 3. succinctly resolved calls lazily during
// evaluation instead, so the error was skippable (an unreached branch),
// catchable (`try`/`?`), and carried the runtime exit code 5; two forward
// references real jq rejects computed a value instead.
//
// Every expectation below was captured from the pinned oracle (`/usr/bin/jq`,
// jq-1.7.1) rather than from succinctly's own output.
// ---------------------------------------------------------------------------

/// A jq builtin succinctly does not implement must still *compile* when it is
/// mentioned somewhere evaluation never reaches -- real jq compiles it, so
/// rejecting it would be a regression #1473's resolution pass introduced.
///
/// The roster in `src/jq/resolve.rs` is what makes this hold, and
/// `jq_builtin_roster_matches_the_pinned_capture` (that module's own tests)
/// checks the roster against `tests/data/jq-builtin-names.txt` entry by entry.
/// This test covers the other half -- that the roster is actually consulted --
/// on a representative sample rather than all 218 names: a whole-roster sweep
/// through the CLI also exercises the *parser*, and `modulemeta` is a
/// pre-existing parse divergence (succinctly's parser demands
/// `modulemeta(...)` where jq's builtin is arity 0) unrelated to resolution.
#[test]
fn test_unimplemented_jq_builtins_still_compile_when_unreached_1473() -> Result<()> {
    for call in [
        "cbrt",
        "hypot(.; .)",
        "fma(.; .; .)",
        "frexp",
        "JOIN(.; .; .; .)",
        "format(.)",
        "input_filename",
        "get_search_list",
        "strflocaltime(.)",
        "significand",
    ] {
        let filter = format!("if false then {call} else 1 end");
        let (stdout, stderr, code) = run_jq_full(&["-c", &filter], Some("null"))?;
        assert_eq!(code, 0, "{call}: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), "1", "{call}: stderr {stderr:?}");
    }
    Ok(())
}

/// A jq builtin succinctly does not implement stays a *runtime* error when the
/// call is actually reached -- the roster defers it, it does not silence it.
#[test]
fn test_unimplemented_jq_builtin_still_errors_when_reached_1473() -> Result<()> {
    let (_stdout, stderr, code) = run_jq_full(&["-c", "cbrt"], Some("8"))?;
    assert_eq!(code, 5, "stderr: {stderr:?}");
    assert!(
        stderr.contains("undefined function: cbrt/0"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// An unresolvable call in a branch that is never taken still fails, and fails
/// before any input is read. jq: `f/3 is not defined`, exit 3.
#[test]
fn test_unresolved_call_in_unreached_branch_is_a_compile_error_1473() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(
        &["-c", "def f(x): x; if false then f(1;2;3) else 1 end"],
        Some("null"),
    )?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert!(
        stderr.contains("f/3 is not defined at <top-level>, line 1:"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// `try`/`catch` and `?` cannot swallow it: compilation fails before
/// evaluation, and thus before `try`, ever begins.
#[test]
fn test_unresolved_call_is_not_catchable_1473() -> Result<()> {
    for filter in [
        r#"def f(x): x; try f(1;2) catch "caught""#,
        "def f(x): x; f(1;2)?",
        r#"try nosuchfn catch "caught""#,
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_eq!(code, 3, "{filter}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout, "", "{filter}: a compile error produces no output");
        assert!(
            stderr.contains("is not defined"),
            "{filter}: stderr {stderr:?}"
        );
    }
    Ok(())
}

/// A forward reference across *different* names -- the pre-existing half of
/// #1473's severe case, which computed `42` where jq rejects the program.
#[test]
fn test_forward_reference_across_names_is_a_compile_error_1473() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", "def f: g; def g: 42; f"], Some("null"))?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert!(
        stderr.contains("g/0 is not defined at <top-level>, line 1:"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// A nested `def` is scoped to its enclosing body and does not leak out of it
/// -- previously an exit-5 runtime error, now jq's exit-3 compile error.
#[test]
fn test_nested_def_does_not_leak_into_outer_scope_1473() -> Result<()> {
    let (_stdout, stderr, code) = run_jq_full(&["-c", "def f: def g: 1; g; g"], Some("null"))?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert!(stderr.contains("g/0 is not defined"), "stderr: {stderr:?}");
    Ok(())
}

/// A `def` parameter binds its bare name as an arity-0 function -- including
/// the `$`-prefixed form, which jq desugars to `def f(a): a as $a | …`, leaving
/// `a` callable. Calling one with arguments is `g/1 is not defined`, not a call
/// to anything in the enclosing scope.
#[test]
fn test_def_parameter_binds_arity_zero_only_1473() -> Result<()> {
    for (filter, want) in [("def f(g): g; f(1)", "1"), ("def f($a): a; f(1)", "1")] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_eq!(code, 0, "{filter}: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), want, "{filter}");
    }

    let (_stdout, stderr, code) = run_jq_full(&["-c", "def f(g): g(1); f(.)"], Some("null"))?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert!(stderr.contains("g/1 is not defined"), "stderr: {stderr:?}");
    Ok(())
}

/// The resolution pass must not reject anything real jq accepts. Each of these
/// exercises a scope rule the pass has to get right, and each was run against
/// the pinned oracle for both its value and its exit code.
#[test]
fn test_resolution_pass_accepts_every_legal_scope_shape_1473() -> Result<()> {
    for (filter, want) in [
        // A def is visible to later siblings, and to itself.
        ("def f: 1; def g: f; g", "1"),
        ("def f(n): if n == 0 then 0 else f(n-1) end; f(3)", "0"),
        // Arity overloading, in both directions (#1376).
        (
            "def f(x): x + 1; def f(x; y): x + y; [f(1), f(2;3)]",
            "[2,5]",
        ),
        ("def f(x): x+1; def f(x;y): (f(x)) + y; f(2;3)", "6"),
        // A later same-arity def shadows, but the earlier one stays bound
        // inside anything defined before the redefinition.
        ("def f: 1; def g: f; def f: 2; g", "1"),
        // An inner def shadows an outer one for its own extent only.
        ("def f: 1; [f, (def f: 2; f), f]", "[1,2,1]"),
        // A def inside a builtin argument, reached through `builtin_kids`.
        ("def f: 3; [1,2] | map(f)", "[3,3]"),
        // A parameter shadowing the function's own name.
        ("def f(f): f; f(7)", "7"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_eq!(code, 0, "{filter}: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), want, "{filter}: stderr {stderr:?}");
    }
    Ok(())
}

/// A plain syntax error is jq's compile error too: exit 3, and no second,
/// stray `Error: compile error` line from `anyhow`'s own reporting (#1473).
#[test]
fn test_syntax_error_exits_with_the_compile_error_code_1473() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", "1 +"], Some("null"))?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert!(stderr.contains("compile error"), "stderr: {stderr:?}");
    assert!(
        !stderr.contains("Error: compile error"),
        "the stray anyhow line is back: {stderr:?}"
    );
    Ok(())
}

/// An unresolvable `include`/`import` is jq's compile error too -- the third
/// kind, alongside a syntax error and an undefined function, and the last one
/// still routing through `anyhow` for exit 1 and a stray `Error: module error`
/// line (#1473). jq 1.7.1 exits 3.
#[test]
fn test_module_error_exits_with_the_compile_error_code_1473() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["-n", r#"include "nonexistent_module_xyz"; ."#], None)?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert!(
        stderr.contains("module") && stderr.contains("not found"),
        "stderr: {stderr:?}"
    );
    assert!(
        !stderr.contains("Error: module error"),
        "the stray anyhow line is back: {stderr:?}"
    );
    Ok(())
}

/// The reported line is the one the offending identifier is written on, not
/// always line 1 -- `report_unresolved_calls` locates it in the filter source.
#[test]
fn test_unresolved_call_reports_its_own_source_line_1473() -> Result<()> {
    let (_stdout, stderr, code) = run_jq_full(&["-c", "def f: 1;\nf\n| nosuch"], Some("null"))?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert!(
        stderr.contains("nosuch/0 is not defined at <top-level>, line 3:"),
        "stderr: {stderr:?}"
    );
    assert!(
        stderr.contains("\n| nosuch"),
        "the offending line should be echoed: {stderr:?}"
    );
    Ok(())
}

/// The identifier search is word-bounded: an undefined `f` must not report the
/// line of some longer identifier that merely contains an `f`.
#[test]
fn test_unresolved_call_line_search_is_word_bounded_1473() -> Result<()> {
    let (_stdout, stderr, code) = run_jq_full(
        &["-c", "def first_thing: 1;\nfirst_thing\n| f"],
        Some("null"),
    )?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert!(
        stderr.contains("f/0 is not defined at <top-level>, line 3:"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// #1473: an unresolvable call reached through an `include`d module has no
/// occurrence in the filter source, so `locate_identifier_from` finds nothing
/// and the diagnostic drops the line marker and source echo rather than
/// inventing a position.
///
/// jq names the module file and line here
/// (`... is not defined at /path/mymod.jq, line 1:` plus the module's own
/// source line); succinctly reports `at <top-level>` with no location. The
/// name, arity and exit code match; only the location does not, for the same
/// reason the in-filter case can cite the wrong occurrence — `Expr::FuncCall`
/// carries no source position, and modules would additionally need the
/// originating *file* threaded through `ModuleLoader`. Recorded in
/// docs/compliance/jq/limitations.md.
#[test]
fn test_unresolved_call_from_included_module_omits_the_location_1473() -> Result<()> {
    let temp_dir = tempfile::tempdir()?;
    std::fs::write(
        temp_dir.path().join("mymod.jq"),
        "def helper: nosuchfn_in_module;",
    )?;

    let (output, code) = spawn_with_signal_retry(
        || {
            let mut cmd = Command::new(succinctly_bin());
            cmd.args(["jq", "-n", "-L"])
                .arg(temp_dir.path())
                .arg(r#"include "mymod"; helper"#);
            cmd
        },
        None,
    )?;

    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(code, 3, "stderr: {stderr}");
    assert!(
        stderr.contains("nosuchfn_in_module/0 is not defined at <top-level>"),
        "stderr: {stderr}"
    );
    assert!(
        !stderr.contains(", line "),
        "no line should be claimed for a call with no in-filter occurrence: {stderr}"
    );
    assert!(stderr.contains("jq: 1 compile error"), "stderr: {stderr}");
    Ok(())
}

/// #2037: jq reports *every* unresolvable call in one compile pass, not just
/// the first -- `jq: N compile errors`. Captured live against the pinned
/// oracle (`/usr/bin/jq` 1.7.1); this filter and its exact three-error output
/// (including each line's trailing padding) are copied byte-for-byte from
/// that capture.
#[test]
fn test_all_unresolved_calls_are_reported_not_just_the_first_2037() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["-n", "def f: 1; f, nosuch, nosuch(1;2), nosuch"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert_eq!(
        stderr,
        "jq: error: nosuch/0 is not defined at <top-level>, line 1:\n\
         def f: 1; f, nosuch, nosuch(1;2), nosuch             \n\
         jq: error: nosuch/2 is not defined at <top-level>, line 1:\n\
         def f: 1; f, nosuch, nosuch(1;2), nosuch                     \n\
         jq: error: nosuch/0 is not defined at <top-level>, line 1:\n\
         def f: 1; f, nosuch, nosuch(1;2), nosuch                                  \n\
         jq: 3 compile errors\n"
    );
    Ok(())
}

/// #2037: a repeated undefined name no longer always cites the first
/// occurrence's line -- each successive report resumes the source search
/// right after the previous match, so the second and third `nosuch1` in
/// `nosuch1 | nosuch2 | nosuch1` are told apart even though
/// `locate_identifier_from` still has no real AST position to work from.
/// Captured live against the pinned oracle, which reports the same three
/// errors in the same order.
#[test]
fn test_repeated_unresolved_name_cites_its_own_occurrence_2037() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-n", "nosuch1 | nosuch2 | nosuch1"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert_eq!(
        stderr,
        "jq: error: nosuch1/0 is not defined at <top-level>, line 1:\n\
         nosuch1 | nosuch2 | nosuch1\n\
         jq: error: nosuch2/0 is not defined at <top-level>, line 1:\n\
         nosuch1 | nosuch2 | nosuch1          \n\
         jq: error: nosuch1/0 is not defined at <top-level>, line 1:\n\
         nosuch1 | nosuch2 | nosuch1                    \n\
         jq: 3 compile errors\n"
    );
    Ok(())
}

/// #2037's original repro (from the issue that motivated this fix): both
/// `nosuch` calls fail to resolve, and jq reports both, one per line, in
/// source order -- not just the first, with `jq: 1 compile error` claiming a
/// count that doesn't match what was actually printed.
#[test]
fn test_original_2037_repro_reports_both_lines() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-n", "def f: 1;\nnosuch\n| nosuch"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert!(
        stderr.contains("nosuch/0 is not defined at <top-level>, line 2:"),
        "stderr: {stderr:?}"
    );
    assert!(
        stderr.contains("nosuch/0 is not defined at <top-level>, line 3:"),
        "stderr: {stderr:?}"
    );
    assert!(
        stderr.contains("jq: 2 compile errors"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// #2037: an unresolved call's *arguments* are only checked once the call
/// itself resolves. Real jq's compiler binds argument closures to the
/// callee's parameter slots, which requires the callee to already be found;
/// an unresolved callee means there is nothing to bind the arguments to, so
/// jq never compiles them and reports only the callee. Verified live: this
/// filter is `nosucha/2 is not defined`, one error, in jq 1.7.1 -- not three.
///
/// Collecting every unresolvable call (rather than stopping at the first, as
/// this same PR does) made this easy to get wrong in the other direction: a
/// naive "keep checking everything" still descends into an unresolved call's
/// own arguments and reports errors real jq's compiler never reaches at all.
#[test]
fn test_unresolved_callee_args_are_not_independently_checked_2037() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-n", "nosucha(nosuchb; nosuchc)"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert_eq!(
        stderr,
        "jq: error: nosucha/2 is not defined at <top-level>, line 1:\n\
         nosucha(nosuchb; nosuchc)\n\
         jq: 1 compile error\n"
    );
    Ok(())
}

/// #2037, the flip side of the test above: once the callee itself *does*
/// resolve, its arguments are checked exactly as before -- an unresolved call
/// inside a resolved call's argument is still reported. Verified live against
/// jq 1.7.1 (`nosuch/0 is not defined`, one error).
#[test]
fn test_resolved_callee_still_checks_its_own_arguments_2037() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-n", "def f(x): x; f(nosuch)"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert_eq!(
        stderr,
        "jq: error: nosuch/0 is not defined at <top-level>, line 1:\n\
         def f(x): x; f(nosuch)               \n\
         jq: 1 compile error\n"
    );
    Ok(())
}

/// #1687 on the jq side. Plain `succinctly jq` collapses duplicate keys on
/// purpose (#1385, matching real jq), so the observable surface here is
/// `--preserve-input`, the extension whose stated job is keeping the input's
/// own formatting.
///
/// The result is deliberately asymmetric, and this pins both halves:
///
/// - `min`/`max`/`min_by`/`max_by` answer a bare `GenericResult::OneCursor`,
///   which `generic_result_to_jq_values` forwards as `JqValue::Cursor`
///   without decoding -- so they now preserve, joining `first(.[])`, which
///   always has.
/// - `sort`/`unique`/`reverse` and the `_by` forms answer a `LazySeq`, and
///   `jq_runner.rs` has no lazy-array `JqValue`: its `LazySeq` arm calls
///   `materialize_atomic()`, producing an `IndexMap`-backed `OwnedValue`.
///   They therefore still collapse -- a pre-existing property of the jq
///   output path, not something #1687 changed: `map(.)` has answered a
///   `LazySeq` since #724/#725 and collapses here identically.
///
/// Closing that second half means giving the jq CLI a streaming array value
/// the way `yq_runner.rs` already has one; filed separately rather than
/// widened into this change.
#[test]
fn test_preserve_input_sort_family_cursor_results_keep_duplicate_keys_1687() -> Result<()> {
    let input = r#"[{"a":1,"a":2},{"b":3}]"#;

    // Control: the whole document, and the long-standing `first` path.
    let (stdout, _, code) = run_jq_full(&["-c", "--preserve-input", "."], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[{\"a\":1,\"a\":2},{\"b\":3}]\n");

    let (stdout, _, code) = run_jq_full(&["-c", "--preserve-input", "first(.[])"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "{\"a\":1,\"a\":2}\n");

    // Single-element results now match it.
    for filter in ["min", "max_by(.a)"] {
        let (stdout, _, code) = run_jq_full(&["-c", "--preserve-input", filter], Some(input))?;
        assert_eq!(code, 0, "{filter}");
        assert_eq!(stdout, "{\"a\":1,\"a\":2}\n", "{filter}");
    }

    // Array-valued results do not, for the reason above. `map(.)` is here as
    // the control proving the cause is the output path rather than #1687.
    for filter in ["map(.)", "sort", "unique"] {
        let (stdout, _, code) = run_jq_full(&["-c", "--preserve-input", filter], Some(input))?;
        assert_eq!(code, 0, "{filter}");
        assert_eq!(
            stdout, "[{\"a\":2},{\"b\":3}]\n",
            "{filter}: jq_runner has no lazy-array JqValue, so a LazySeq materializes"
        );
    }

    Ok(())
}

/// #1687 must not disturb plain jq mode, where collapsing duplicate keys is
/// the *correct* behaviour (#1385) -- every row below re-verified live
/// against the pinned jq 1.7.1.
#[test]
fn test_sort_family_still_collapses_in_plain_jq_mode_1687() -> Result<()> {
    let input = r#"[{"a":1,"a":2},{"b":3}]"#;
    for (filter, want) in [
        ("sort", "[{\"a\":2},{\"b\":3}]\n"),
        ("reverse", "[{\"b\":3},{\"a\":2}]\n"),
        ("unique", "[{\"a\":2},{\"b\":3}]\n"),
        ("min", "{\"a\":2}\n"),
        ("max", "{\"b\":3}\n"),
    ] {
        let (stdout, _, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{filter}");
        assert_eq!(stdout, want, "{filter}");
    }
    Ok(())
}

/// #1687: the error and control paths through the new native arms, which the
/// happy-path tests above never reach — `sort_key_generic`'s `Err`, the
/// `sort_family_control` conversion, `fanout_arg_generic`'s `body`-escape and
/// argument-escape arms, and `reduce`'s input-control propagation.
///
/// Every row is real jq 1.7.1's own output and exit code, captured live: these
/// are all shapes with a jq oracle, so there is no reason to pin anything
/// weaker than parity.
#[test]
fn test_1687_native_arms_propagate_errors_like_jq() -> Result<()> {
    let input = "[10,20,30,40]";

    // An error raised while computing a sort key aborts the whole builtin with
    // no partial output — the atomicity `eval::builtin_min_by` and friends
    // already had, now also on the cursor-native path.
    for filter in [
        "sort_by(error(\"x\"))",
        "min_by(error(\"x\"))",
        "unique_by(error(\"x\"))",
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 5, "{filter}: stderr {stderr}");
        assert_eq!(stdout, "", "{filter}: no partial output");
        assert!(stderr.contains(": x"), "{filter}: stderr {stderr}");
    }

    // An error inside `limit`'s `n` generator, and inside its body, both reach
    // the caller through `fanout_arg_generic` rather than being swallowed.
    for filter in ["[limit((1,error(\"x\")); .[])]", "[limit(2; error(\"x\"))]"] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 5, "{filter}: stderr {stderr}");
        assert_eq!(stdout, "", "{filter}");
        assert!(stderr.contains(": x"), "{filter}: stderr {stderr}");
    }

    // `reduce` is single-shot, so a control anywhere in its input stream
    // discards the prefix and propagates alone — and `?` suppresses an
    // ordinary error there, matching `eval::eval_reduce`'s `suppress_or_raise`.
    let (stdout, stderr, code) = run_jq_full(
        &["-c", "reduce (1,error(\"x\")) as $x (0; .+1)"],
        Some(input),
    )?;
    assert_eq!(code, 5, "stderr {stderr}");
    assert_eq!(stdout, "");

    let (stdout, _, code) = run_jq_full(
        &["-c", "reduce (1,error(\"x\")) as $x (0; .+1)?"],
        Some(input),
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "");

    // An empty array answers `null` for all four min/max spellings, before any
    // key is computed.
    for filter in ["min", "max", "min_by(.)", "max_by(.)"] {
        let (stdout, _, code) = run_jq_full(&["-c", filter], Some("[]"))?;
        assert_eq!(code, 0, "{filter}");
        assert_eq!(stdout, "null\n", "{filter}");
    }

    Ok(())
}

/// #1687: `limit`/`nth` must still hand a live `input`/`inputs` queue to
/// `eval.rs` untouched — the #1309 guard is the one deferral
/// `fanout_arg_generic` did *not* replace, because probing the queue here
/// would drain it as a side effect before the fallback ever ran.
///
/// This covers both bridges: `bridge_to_full_evaluator_flow` (reached from
/// `each_limit_generic`, i.e. `limit` under a demand-driven consumer) and
/// `Expr::NthExpr`'s own. Both rows are jq 1.7.1's own output.
#[test]
fn test_1687_limit_and_nth_still_bridge_a_live_input_queue() -> Result<()> {
    let inputs = "1\n2\n3\n4\n";

    // `first(...)` routes through `each_limit_generic`, the sink-side arm.
    let (stdout, code) = run_jq_stdin("first(limit(inputs; 10,20,30))", inputs, &[])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "10\n");

    // Bare `limit`: `inputs` yields 2,3,4 against the first document, so the
    // body runs once per value of `n`.
    let (stdout, code) = run_jq_stdin("[limit(inputs; 10,20)]", inputs, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[10,20,10,20,10,20]\n");

    let (stdout, code) = run_jq_stdin("nth(inputs; 10,20,30)", inputs, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "30\n");

    Ok(())
}

/// #1687 regression guard for #1755's rule. The `_by` spellings compute a key
/// per element and never need the element's own value, so #1687's first cut
/// skipped decoding it — which silently dropped `eval.rs`'s check that an
/// undecodable element must *raise* rather than sort in as `""`.
///
/// The gap only shows when the bad element never reaches the output, so
/// nothing else surfaces it. succinctly's semi-index accepts these documents
/// where real jq rejects them at parse time, so there is no jq oracle here;
/// the contract being pinned is #1755's own, and `main`'s behaviour.
#[test]
fn test_by_spellings_still_raise_on_an_undecodable_element_1687() -> Result<()> {
    // A lone surrogate, a bad \u escape, and an unknown escape: all three are
    // spans the semi-index accepts and the decoder rejects.
    for bad in [r"\ud800", r"\uZZZZ", r"\x"] {
        let input = format!(r#"[{{"a":2,"s":"{bad}"}},{{"a":1,"s":"ok"}}]"#);

        // `length` never emits the offending element, so only the element
        // decode-check can catch it.
        for filter in [
            "sort_by(.a) | length",
            "unique_by(.a) | length",
            "min_by(.a).a",
            "max_by(.a).a",
        ] {
            let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(&input))?;
            assert_eq!(
                code, 5,
                "{filter} on {bad}: stdout {stdout:?} stderr {stderr}"
            );
            assert_eq!(stdout, "", "{filter} on {bad}");
        }

        // The bare spellings decode the element as their comparison key, so
        // they were never affected — pinned as the control.
        let (stdout, _, code) = run_jq_full(&["-c", "sort | length"], Some(&input))?;
        assert_eq!(code, 5, "sort on {bad}");
        assert_eq!(stdout, "", "sort on {bad}");
    }
    Ok(())
}

/// #1687: the `limit` sink arm's input-queue bridge — the one deferral
/// `fanout_arg_each_generic` does *not* replace, because probing a live
/// `input`/`inputs` queue would drain it as a side effect before the fallback
/// ran.
///
/// Reaching it needs a shape that skips the *top-level* input-queue bridge in
/// `eval_with_cursor_using`, which `takes_input_queue_bridge` declines for a
/// query that also uses a cursor-metadata builtin (#1504). `limit(inputs; line)`
/// is such a shape; `first(limit(inputs; ...))` is not, because
/// `eval_first_or_last_generic`'s own guard fires first. That distinction is
/// why this test exists separately from
/// `test_1687_limit_and_nth_still_bridge_a_live_input_queue`.
///
/// `line` answers 0 rather than a real line number here: the bridge
/// materializes the input and re-indexes it, so position metadata is gone.
/// That is a pre-existing consequence of the guard — #1687 did not change its
/// condition, only removed a separate bare-`Comma` disjunct beside it — and it
/// sits awkwardly with #1504's own purpose, which was to keep `line` working
/// alongside `inputs`. Pinned as the current behaviour, not endorsed.
#[test]
fn test_limit_sink_arm_bridges_a_live_input_queue_1687() -> Result<()> {
    let inputs = "1\n2\n3\n4\n";

    let (stdout, code) = run_jq_stdin("limit(inputs; line)", inputs, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(
        stdout, "0\n0\n0\n",
        "known gap: the bridge loses position metadata"
    );

    // Same arm, reached through a `Comma` sibling rather than as the whole
    // program, so the bridge's `drain_result_generic` half runs too.
    let (stdout, code) = run_jq_stdin("(limit(inputs; line), 1)", inputs, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "0\n0\n0\n1\n");

    Ok(())
}

/// #1687: `sort_family_control`'s non-`Error` half. A `halt_error` inside a
/// sort key aborts the whole builtin with jq's own exit code and stderr —
/// byte-identical to jq 1.7.1, which writes `10\n` and exits 5 (compared with
/// `od -c`, since `halt_error`'s whole point is raw stderr).
///
/// The `Break` arm beside it is not reachable from any query this CLI can
/// parse: `break $out` needs an enclosing `label`, `Expr::Label` has no native
/// `eval_single` arm, so a label above `sort_by` routes the whole expression
/// through the wildcard bridge before this arm runs. Same "unreachable but
/// exhaustive" shape `Expr::Array`'s own `Break` arm documents (#1064).
#[test]
fn test_sort_family_propagates_halt_like_jq_1687() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", "sort_by(halt_error)"], Some("[10,20,30]"))?;
    assert_eq!(code, 5, "stderr {stderr}");
    assert_eq!(stdout, "");
    assert_eq!(stderr, "10\n");
    Ok(())
}

/// #2057: a child that exits *without reading stdin* must not fail the test
/// with `Broken pipe`.
///
/// Every filter here fails to compile, so `succinctly jq` reports the error
/// and exits 3 having never touched stdin. Writing to that closed pipe is
/// then the normal outcome, not a symptom of load -- which is why the four
/// recorded #2057 failures were all compile-error tests, and why re-running
/// the job did not clear them.
///
/// In CI the race is only *biased*, not decided: the few-byte payloads those
/// tests use land in the pipe buffer and succeed whenever the parent reaches
/// its write first. This test removes the bias instead of relying on it. The
/// payload spans many `write` calls, so the child -- which exits in
/// milliseconds -- is certain to have exited before the last of them,
/// whichever side started first. That is the narrower case where payload
/// size is the discriminator at all; for an already-exited child `BrokenPipe`
/// does not depend on buffer capacity.
///
/// Without the `BrokenPipe` arm in `write_stdin_then_wait` this therefore
/// fails every run rather than occasionally, which is what makes it a usable
/// pin for a bug whose own signature in CI is intermittent.
#[test]
fn test_compile_error_with_unread_stdin_is_not_a_broken_pipe_2057() -> Result<()> {
    let payload = "0\n".repeat(2 * 1024 * 1024);
    for filter in ["nosuchfn", "def f(x): x; f(1;2)"] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(&payload))?;
        assert_eq!(code, 3, "{filter}: stderr {stderr:?}");
        assert_eq!(stdout, "", "{filter}: a compile error produces no output");
        assert!(
            stderr.contains("is not defined"),
            "{filter}: stderr {stderr:?}"
        );
    }
    Ok(())
}

/// #1409: an isolated sub-expression's outputs must continue the rest of
/// the pipe from *their own* path, not the ambient pre-isolation one.
///
/// Several arms of `eval_pipe_with_path_context_internal` evaluate a
/// sub-expression with an empty `rest` -- because the construct scopes
/// something `rest` must stay outside of -- and only afterwards continue the
/// real `rest`. `Field`/`Index`/`Iterate` build an updated path only when
/// they have a non-empty `rest` to recurse into, so isolation used to hand
/// the continuation bare values and a stale path: every wrapper below
/// reported `"a"` for all three elements instead of `0`, `1`, `2`.
///
/// The oracle is the un-wrapped pipeline, and `path()` agrees with real jq
/// 1.7.1 on each of these shapes (`jq 'path(.a | (try .[] catch empty))'`
/// => `["a",0]`, `["a",1]`, `["a",2]`), so wrapper and un-wrapped form
/// disagreeing was unambiguously the bug rather than an open question.
#[test]
fn test_isolated_subexpr_threads_per_output_path_1409() -> Result<()> {
    let input = r#"{"a":[1,2,3]}"#;

    // The un-wrapped pipeline every wrapper below has to agree with.
    let (baseline, _, code) = run_jq_full(&["-c", ".a | .[] | key"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(baseline, "0\n1\n2\n");

    for filter in [
        ".a | (try .[] catch empty) | key",
        ".a | (try .[]) | key",
        ".a | (label $out | .[]) | key",
        ".a | (if true then .[] else empty end) | key",
        ".a | (def f: .[]; f) | key",
        ".a | limit(3; .[]) | key",
        // `As` reaches its own path-context arm only when `expr` or `body`
        // needs path context on its own; `select(key >= 0)` is what routes
        // this shape there. The bare `. as $x | .[]` form is a separate,
        // still-open routing gap (#2072): widening the guard to consult
        // `rest` reaches it, but regresses `.x as $v | $v | file_index`,
        // because `substitute_bound_var` re-materialises the bound value as
        // a literal and erases the node identity real yq keeps.
        ".a | (. as $x | (.[] | select(key >= 0))) | key",
        ".a | (. as [$x] | (.[] | select(key >= 0))) | key",
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{filter}: {stderr}");
        assert_eq!(stdout, baseline, "{filter} disagrees with `.a | .[] | key`");
    }

    // The same threading, observed through `path` rather than `key`, so a
    // regression that produced the right *last* component but the wrong
    // prefix would still be caught.
    let (stdout, _, code) = run_jq_full(&["-c", ".a | (try .[] catch empty) | path"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[\"a\",0]\n[\"a\",1]\n[\"a\",2]\n");

    // A non-fan-out navigational body threads its single component too.
    let (stdout, _, code) = run_jq_full(
        &["-c", ".a | (try .b catch empty) | path"],
        Some(r#"{"a":{"b":{"c":1}}}"#),
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[\"a\",\"b\"]\n");

    Ok(())
}

/// #1409: the probe that carries each output's path sits *inside* the
/// isolated pipe, so it must not widen what the construct scopes.
///
/// This is the property that ruled out `Comma`'s own fix (#1509) for these
/// arms: rewriting `try f catch c | rest` as `try (f | rest) catch (c |
/// rest)` would let an error raised by `rest` be caught by the `try`'s own
/// handler, which real jq never does (`jq '.a | (try .[] catch "CAUGHT") |
/// (., error("boom"))'` prints the first element, then fails with `boom`).
#[test]
fn test_isolated_subexpr_probe_does_not_widen_catch_scope_1409() -> Result<()> {
    let input = r#"{"a":[1,2,3]}"#;

    // `error("boom")` is raised by `rest`, outside the `try` -- the handler
    // must not see it, so this fails rather than printing `"CAUGHT"`.
    let (stdout, stderr, code) = run_jq_full(
        &[
            "-c",
            r#".a | (try .[] catch "CAUGHT") | (key, error("boom"))"#,
        ],
        Some(input),
    )?;
    assert_eq!(code, 5, "rest's own error must escape the try: {stderr}");
    assert_eq!(stdout, "0\n");
    assert!(stderr.contains("boom"), "stderr: {stderr}");
    assert!(!stdout.contains("CAUGHT"), "stdout: {stdout}");

    // A `label`'s break scope is likewise unwidened: the `break` below
    // belongs to the *inner* label, and the outer one still sees nothing.
    let (stdout, _, code) = run_jq_full(&["-c", ".a | (label $in | .[]) | key"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "0\n1\n2\n");

    Ok(())
}

/// #1409: a `catch` handler's outputs stay on the ambient path rather than
/// being probed.
///
/// The handler runs against the error *payload*, which is not a node of the
/// document, so probing it would name a path that does not exist: `try
/// error({"b":9}) catch .b` would claim `["a","b"]` even though nothing
/// lives there. Real jq refuses the question outright (`path(.a | (try
/// error({"b":9}) catch .b))` => `Invalid path expression`), so there is no
/// oracle demanding a deeper answer -- and inventing one is strictly worse
/// than the ambient path this evaluator already reported.
#[test]
fn test_catch_handler_outputs_keep_ambient_path_1409() -> Result<()> {
    let (stdout, _, code) = run_jq_full(
        &["-c", r#".a | (try error({"b":9}) catch .b) | path"#],
        Some(r#"{"a":{"b":1}}"#),
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[\"a\"]\n");

    // A prefix produced before the error keeps its own probed path, while
    // the handler's output falls back to the ambient one -- both encodings
    // coexisting in a single result.
    let (stdout, _, code) = run_jq_full(
        &[
            "-c",
            r#".a | (try (.[], error("x")) catch "C") | [path, .]"#,
        ],
        Some(r#"{"a":[1,2,3]}"#),
    )?;
    assert_eq!(code, 0);
    assert_eq!(
        stdout,
        "[[\"a\",0],1]\n[[\"a\",1],2]\n[[\"a\",2],3]\n[[\"a\"],\"C\"]\n"
    );

    Ok(())
}

/// #2061: every arm of the cursor-native `path()` walk, exercised through the
/// CLI so it reaches `eval_generic.rs`'s `Builtin::Path` rather than
/// `eval.rs`'s library-only entry point.
///
/// Every expectation is jq 1.7.1's own output, re-verified live: this arm
/// exists to be faster, not to behave differently, so parity is the whole
/// specification.
#[test]
fn test_path_cursor_native_navigational_shapes_2061() -> Result<()> {
    for (filter, input, want) in [
        // Identity, field, nested field.
        ("path(.)", "{\"a\":1}", "[]\n"),
        ("path(.a)", "{\"a\":1}", "[\"a\"]\n"),
        ("path(.a.b)", "{\"a\":{\"b\":1}}", "[\"a\",\"b\"]\n"),
        // A path need not exist: jq yields it and keeps navigating through
        // the absent node as if it were null.
        ("path(.a)", "{}", "[\"a\"]\n"),
        ("path(.a.b)", "{}", "[\"a\",\"b\"]\n"),
        ("path(.a.b)", "null", "[\"a\",\"b\"]\n"),
        // Index, including the float spelling (#1088) and a negative index,
        // neither of which needs the array's length.
        ("path(.[0])", "[7,8]", "[0]\n"),
        ("path(.[0])", "[]", "[0]\n"),
        ("path(.[2.0])", "[1,2,3]", "[2.0]\n"),
        ("path(.[-1])", "[1,2,3]", "[-1]\n"),
        // Iterate over both container kinds.
        ("[path(.[])]", "{\"a\":1,\"b\":2}", "[[\"a\"],[\"b\"]]\n"),
        ("[path(.[])]", "[7,8]", "[[0],[1]]\n"),
        ("[path(.[])]", "{}", "[]\n"),
        // Comma, pipe through a fan-out, and `?`.
        ("[path(.a,.b)]", "{\"a\":1,\"b\":2}", "[[\"a\"],[\"b\"]]\n"),
        (
            "[path(.[]|.x)]",
            "[{\"x\":1},{\"x\":2}]",
            "[[0,\"x\"],[1,\"x\"]]\n",
        ),
        ("[path(.a?)]", "[1,2]", "[]\n"),
        ("[path((.a)?)]", "[1,2]", "[]\n"),
        // A non-navigable body still works -- it defers to the materializing
        // resolver rather than being rejected.
        ("[path(.[]|select(.>1))]", "[1,2,3]", "[[1],[2]]\n"),
        ("path(.[\"a\"])", "{\"a\":1}", "[\"a\"]\n"),
    ] {
        let (stdout, code) = run_jq_stdin(filter, input, &["-c"])?;
        assert_eq!(code, 0, "`{filter}` on `{input}`");
        assert_eq!(stdout, want, "`{filter}` on `{input}`");
    }
    Ok(())
}

/// #2061: the error arms of the same walk. Each message is jq 1.7.1's own,
/// and comes from the same `EvalError` constructor the materializing resolver
/// uses, so the two cannot drift.
#[test]
fn test_path_cursor_native_type_errors_2061() -> Result<()> {
    for (filter, input, want) in [
        ("path(.a)", "[1,2]", "Cannot index array with string \"a\""),
        ("path(.a)", "5", "Cannot index number with string \"a\""),
        ("path(.a)", "\"s\"", "Cannot index string with string \"a\""),
        ("path(.a)", "true", "Cannot index boolean with string \"a\""),
        (
            "path(.a.b)",
            "{\"a\":1}",
            "Cannot index number with string \"b\"",
        ),
        ("path(.[0])", "{}", "Cannot index object with number"),
        ("path(.[0])", "5", "Cannot index number with number"),
        ("path(.[])", "null", "Cannot iterate over null (null)"),
        ("path(.[])", "5", "Cannot iterate over number (5)"),
    ] {
        let (stdout, stderr, code) = run_jq_stdin_streams(filter, input, &["-c"])?;
        assert_eq!(code, 5, "`{filter}` on `{input}`: stdout {stdout:?}");
        assert!(
            stderr.contains(want),
            "`{filter}` on `{input}`: wanted {want:?}, got {stderr:?}"
        );
    }
    Ok(())
}

/// #2061: a partial result produced before a later sibling errors must still
/// be emitted -- jq's generator never un-emits an output it already produced.
///
/// Discarding it is the bug the evaluator-parity and golden suites caught in
/// this change's first cut, so it is pinned directly rather than left to them.
#[test]
fn test_path_cursor_native_keeps_output_before_a_later_error_2061() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_stdin_streams("path(.a.b, .c.d)", "{\"a\":{\"b\":1},\"c\":1}", &["-c"])?;
    assert_eq!(code, 5, "stderr {stderr}");
    assert_eq!(stdout, "[\"a\",\"b\"]\n");
    assert!(
        stderr.contains("Cannot index number with string \"d\""),
        "{stderr}"
    );
    Ok(())
}

/// #2061: the validity walk's lazy #1642 collision map, whose fallback branch
/// only runs once an undecodable *key* actually appears.
///
/// All four layouts matter and are checked separately, because the branch
/// re-walks the object's *preceding* keys to seed the map: a fallback key
/// first exercises the empty-prefix case, a fallback key after a clean one
/// exercises the re-walk itself, two fallback keys exercise the map holding
/// more than one, and a fallback key whose display form collides with a real
/// key exercises the guard actually raising. Byte-identical to the eager map
/// on all four, verified against `main`.
///
/// **The key must be undecodable, not merely lossy.** An earlier version of
/// this test used raw invalid UTF-8 (`"\xff\xfe"`) and reached none of this:
/// those bytes decode lossily, `string_decode_error()` answers `None`, and
/// `key_display_string_kind` therefore reports them as ordinary keys, so the
/// eager path never engages. Only the `\uXXXX` family produces a genuine
/// decode failure. An undecodable *value* does not reach it either -- that is
/// the walk's separate scalar arm. Confirmed by planting a probe in the
/// branch and checking which documents actually execute it, rather than
/// assuming from the test passing.
#[test]
fn test_path_validity_walk_lazy_collision_map_2061() -> Result<()> {
    // Fallback key first: the re-walk runs with an empty prefix.
    let (stdout, code) = run_jq_stdin("[path(.[])]", r#"{"\ud800":1,"a":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[[\"\\\\ud800\"],[\"a\"]]\n");

    // Fallback key after a clean one: the re-walk has a prefix to seed from.
    let (stdout, code) = run_jq_stdin("[path(.[])]", r#"{"a":1,"\ud800":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[[\"a\"],[\"\\\\ud800\"]]\n");

    // Two distinct fallback keys, and a clean key on either side of one.
    let (stdout, code) = run_jq_stdin("[path(.[])]", r#"{"\ud800":1,"\ud801":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[[\"\\\\ud800\"],[\"\\\\ud801\"]]\n");

    let (stdout, code) = run_jq_stdin("[path(.[])]", r#"{"a":1,"\ud800":2,"b":3}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[[\"a\"],[\"\\\\ud800\"],[\"b\"]]\n");

    // A navigation that never visits the undecodable key still sees it,
    // because the walk validates the whole document -- the behaviour #2061
    // deliberately preserved rather than trading away for speed.
    let (stdout, code) = run_jq_stdin("path(.a)", r#"{"\ud800":1,"a":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[\"a\"]\n");

    Ok(())
}

/// #2061: the collision the lazy map's guard exists to catch still raises --
/// an undecodable key whose display spelling collides with a real key of that
/// same name, which a display-keyed map cannot hold both of (#1642).
///
/// Checked in all three positions relative to the clean key, since the lazy
/// map only seeds itself from the prefix once a fallback key appears: getting
/// the seeding wrong would turn one of these into a silent success.
#[test]
fn test_path_validity_walk_still_raises_on_a_colliding_key_2061() -> Result<()> {
    for doc in [
        r#"{"\\ud800":1,"\ud800":2}"#,
        r#"{"\ud800":1,"\ud800":2}"#,
        r#"{"a":1,"\ud800":2,"\ud800":3}"#,
    ] {
        let (stdout, stderr, code) = run_jq_stdin_streams("path(.a)", doc, &["-c"])?;
        assert_eq!(code, 5, "{doc}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout, "", "{doc}");
        assert!(stderr.contains("is ambiguous"), "{doc}: {stderr}");
    }
    Ok(())
}

/// #2061: a `\uXXXX`-family decode failure anywhere in the document still
/// makes `path()` raise, unchanged from before this change.
///
/// This is the validity gate the cursor walk deliberately keeps: dropping it
/// would have made `path()` roughly 8x faster still, but #1755/#1953 chose to
/// raise on undecodable content rather than silently substitute, and a
/// performance change is not the place to reverse that.
#[test]
fn test_path_still_raises_on_an_undecodable_sibling_2061() -> Result<()> {
    for bad in [r"\ud800", r"\uZZZZ", r"\x", r"\u12"] {
        let input = format!("{{\"a\":\"{bad}\",\"d\":5}}");
        let (stdout, stderr, code) = run_jq_stdin_streams("path(.d)", &input, &["-c"])?;
        assert_eq!(code, 5, "{bad}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout, "", "{bad}");
    }
    Ok(())
}

/// #2061: the walk's remaining arms — navigating *through* an absent node, and
/// the multi-stage pipe forms.
///
/// These are the shapes the first round of tests missed: `Iterate` and the
/// index/field steps each have a distinct `PathNode::Absent` arm, reached only
/// when an earlier component did not exist in the document, and a pipe of more
/// than two stages takes a different branch from a two-stage one. Every row is
/// jq 1.7.1's own output.
#[test]
fn test_path_cursor_native_absent_nodes_and_pipes_2061() -> Result<()> {
    for (filter, input, want) in [
        // Navigating on through an absent node: jq keeps yielding the path.
        ("path(.a.b.c)", "{}", "[\"a\",\"b\",\"c\"]\n"),
        ("path(.a[0])", "{}", "[\"a\",0]\n"),
        // Identity and a parenthesised stage inside a pipe.
        ("path(.|.a)", "{}", "[\"a\"]\n"),
        ("path((.a)|.b)", "{}", "[\"a\",\"b\"]\n"),
        // Three stages: the `rest.len() > 1` branch, distinct from two.
        ("path(.a|.|.b)", "{}", "[\"a\",\"b\"]\n"),
        (
            "path(.a.b.c)",
            "{\"a\":{\"b\":{\"c\":1}}}",
            "[\"a\",\"b\",\"c\"]\n",
        ),
        // Iterate as a later pipe stage, over both container kinds.
        ("path(.[]|.[])", "{\"a\":{\"b\":1}}", "[\"a\",\"b\"]\n"),
        ("path(.[]|.[])", "{\"a\":[1,2]}", "[\"a\",0]\n[\"a\",1]\n"),
        ("path(.a[])", "{\"a\":[1,2]}", "[\"a\",0]\n[\"a\",1]\n"),
        ("path(.a[])", "{\"a\":{\"b\":1}}", "[\"a\",\"b\"]\n"),
        // An empty container iterates to nothing rather than erroring.
        ("[path(.[]|.[])]", "{}", "[]\n"),
    ] {
        let (stdout, code) = run_jq_stdin(filter, input, &["-c"])?;
        assert_eq!(code, 0, "`{filter}` on `{input}`");
        assert_eq!(stdout, want, "`{filter}` on `{input}`");
    }

    // Iterating an absent node raises, exactly as iterating an explicit null
    // does -- the `PathNode::Absent` arm of the `Iterate` step.
    for (filter, input) in [("path(.a[])", "{}"), ("path(.a|.[])", "{}")] {
        let (stdout, stderr, code) = run_jq_stdin_streams(filter, input, &["-c"])?;
        assert_eq!(code, 5, "`{filter}` on `{input}`: stdout {stdout:?}");
        assert!(
            stderr.contains("Cannot iterate over null"),
            "`{filter}` on `{input}`: {stderr}"
        );
    }

    // A type error reached *after* an absent step still names the right type.
    let (_, stderr, code) = run_jq_stdin_streams("path(.a.b.c)", "{\"a\":[1,2]}", &["-c"])?;
    assert_eq!(code, 5);
    assert!(
        stderr.contains("Cannot index array with string \"b\""),
        "{stderr}"
    );

    Ok(())
}
